// Calendar-based "Fact of the Day" / "Thought of the Day" content for the
// Coach welcome screen. Split from welcome.ts (which owns the greeting and
// priority logic) purely because this table is large.
//
// Keyed by month/day, NOT by a dayOfYear-modulo index — see getDailyFact
// below. One entry per calendar date (365) plus one dedicated 29 February
// entry for leap years (366 total), so a given date always maps to the same
// entry every year, with no drift around leap years.
//
// `eyebrow` and `emoji` are deliberately NOT stored per entry — at this
// size (366 records) storing two fields that are always 1:1 with `kind`
// would just be repeated literal text with no informational value. See
// KIND_META below.
//
// Organised as one const array per month (JAN_FACTS, FEB_FACTS, ...),
// concatenated into DAILY_FACTS at the bottom — purely to keep this file
// navigable; nothing outside this file depends on the per-month split.

export type DailyFactKind = 'fact' | 'thought';

export interface DailyFact {
  id: string;
  month: number; // 1-12
  day: number; // 1-31 (or 29 for the dedicated Feb-29 leap-day entry)
  kind: DailyFactKind;
  /** Short line shown on the Daily Highlight card. */
  summary: string;
  /** Fuller explanation shown in the detail view. Paragraphs separated by '\n\n'. */
  detailBody: string;
}

export const KIND_META: Record<DailyFactKind, { eyebrow: string; emoji: string }> = {
  fact: { eyebrow: 'Fact of the Day', emoji: '✨' },
  thought: { eyebrow: 'Thought of the Day', emoji: '💡' },
};

const JAN_FACTS: DailyFact[] = [
  { id: 'fresh-start', month: 1, day: 1, kind: 'thought', summary: 'A new year is a natural reset point for habits, routines and classroom goals.', detailBody: 'Psychologists call this the "fresh start effect" — people are more likely to commit to a goal right after a symbolic date change than on an ordinary day.\n\nClassroom idea: Ask students for one small, specific goal for the term instead of a vague resolution.' },
  { id: 'zero-india', month: 1, day: 2, kind: 'fact', summary: 'The concept of zero as a number was formalised by Indian mathematicians.', detailBody: 'Indian mathematician Brahmagupta gave the first known rules for arithmetic with zero in the 7th century, a foundation later carried to the world via Arabic scholarship.\n\nFor teachers: A strong example of India\'s historical contribution to mathematics beyond memorised trivia.' },
  { id: 'earth-tilt', month: 1, day: 3, kind: 'fact', summary: "Seasons happen because Earth's axis is tilted, not because of distance from the Sun.", detailBody: "Earth is actually slightly closer to the Sun in January than in July (Northern Hemisphere winter) — it's the 23.5° axial tilt that drives seasons, not orbital distance.\n\nFor teachers: A common misconception worth correcting directly with a simple globe demonstration." },
  { id: 'braille', month: 1, day: 4, kind: 'fact', summary: 'Louis Braille invented the braille reading system for the blind at just 15 years old.', detailBody: 'Braille, born in France in 1809, lost his sight in a childhood accident and later developed the six-dot tactile system still used worldwide today.\n\nFor teachers: A strong example of accessible design, and of a young person\'s invention still in daily use two centuries later.' },
  { id: 'retrieval-practice', month: 1, day: 5, kind: 'thought', summary: 'Testing yourself on material helps you remember it better than simply re-reading it.', detailBody: "This is called the 'testing effect' — actively recalling information strengthens memory more than passive review, even when the test itself isn't graded.\n\nClassroom idea: A two-minute recall quiz at the start of class can do more for retention than reviewing yesterday's notes." },
  { id: 'light-speed', month: 1, day: 6, kind: 'fact', summary: 'Sunlight takes about 8 minutes to reach Earth.', detailBody: "Light travels at roughly 300,000 km per second, and the Sun is about 150 million km away — so if the Sun vanished, we'd still see it shine for 8 more minutes.\n\nFor teachers: A vivid way to make astronomical distances concrete for students." },
  { id: 'silk-road', month: 1, day: 7, kind: 'fact', summary: "The Silk Road wasn't a single road — it was a network of trade routes across Asia.", detailBody: 'For centuries it carried not just silk but spices, paper, and ideas between China, India, Persia and Europe.\n\nFor teachers: Useful when teaching that trade routes have always spread culture and knowledge, not just goods.' },
  { id: 'bones', month: 1, day: 8, kind: 'fact', summary: 'Babies are born with about 300 bones; adults have only 206.', detailBody: 'Many bones fuse together as a child grows — the skull alone starts as several separate plates that gradually join.\n\nFor teachers: A good hook when introducing the skeletal system, especially the idea that the body changes structurally, not just in size.' },
  { id: 'growth-mindset', month: 1, day: 9, kind: 'thought', summary: "Praising effort ('you worked hard') builds more resilience than praising ability ('you're so smart').", detailBody: "Ability-based praise can make students afraid to attempt harder problems, since failing would contradict the label. Effort-based praise keeps the focus on what's within their control.\n\nTry this: swap one 'you're so smart' for 'I saw how hard you worked on that' this week." },
  { id: 'internet-invention', month: 1, day: 10, kind: 'fact', summary: "The World Wide Web and 'the internet' are not the same thing.", detailBody: 'The internet is the global network of connected computers, built from the 1960s onward; the Web — pages linked by URLs — was invented by Tim Berners-Lee in 1989 as one application that runs on it.\n\nFor teachers: A useful distinction when discussing how technology layers build on each other.' },
  { id: 'question-thinking', month: 1, day: 11, kind: 'thought', summary: 'A good question is often more valuable to learning than a quick correct answer.', detailBody: "Answers close a topic; questions open it. Encouraging 'why' and 'what if' questions builds the habit of thinking past the first plausible answer.\n\nClassroom idea: End a lesson by asking students to write one question they're still curious about." },
  { id: 'vivekananda', month: 1, day: 12, kind: 'fact', summary: "12 January is National Youth Day in India, marking Swami Vivekananda's birthday.", detailBody: "Vivekananda, born in 1863, is remembered for his 1893 speech at the World's Parliament of Religions in Chicago and for his emphasis on education, self-confidence and service.\n\nFor teachers: A fitting day for a short discussion on purpose and self-belief with older students." },
  { id: 'rivers-civilisation', month: 1, day: 13, kind: 'fact', summary: "Most of the world's earliest civilisations grew up along major rivers.", detailBody: 'The Indus, Nile, Tigris-Euphrates and Yellow River valleys all gave rise to early cities — rivers provided water, fertile soil and transport in one package.\n\nFor teachers: A good pattern to point out before naming any specific ancient civilisation.' },
  { id: 'unit-fractions', month: 1, day: 14, kind: 'fact', summary: "Ancient Egyptians only used 'unit fractions' — fractions with 1 as the numerator.", detailBody: 'Instead of writing 3/4, they would express it as a sum like 1/2 + 1/4 — a very different, more cumbersome system than the one we use today.\n\nFor teachers: A fun way to show students that today\'s fraction notation is a convenience, not the only possible one.' },
  { id: 'sleep-consolidation', month: 1, day: 15, kind: 'thought', summary: 'Sleep plays an active role in consolidating what was learned that day.', detailBody: "During sleep, the brain replays and strengthens new memories, which is part of why cramming right before a test is far less effective than reviewing material a night or two earlier.\n\nFor teachers: Worth mentioning to older students ahead of exam season." },
  { id: 'nonverbal-communication', month: 1, day: 16, kind: 'thought', summary: 'A large part of communication is non-verbal — tone, posture and expression carry meaning too.', detailBody: "Students often read a teacher's body language before they process the words, especially younger ones.\n\nClassroom idea: When giving feedback, check that your tone and expression match your words, especially for corrections." },
  { id: 'printing-press', month: 1, day: 17, kind: 'fact', summary: 'The printing press, invented by Gutenberg around 1440, made books affordable for the first time.', detailBody: 'Before this, books were hand-copied and enormously expensive, so literacy was largely limited to the wealthy and religious institutions.\n\nFor teachers: A clear example of how a single technology can widen access to education.' },
  { id: 'exit-ticket', month: 1, day: 18, kind: 'thought', summary: 'Ending a lesson with one quick question tells you more than you\'d think.', detailBody: "A simple 'exit ticket' — one question answered on the way out — surfaces what actually landed, often more honestly than asking 'any questions?' to the whole class.\n\nClassroom idea: Try 'write one thing that's still unclear' instead of 'write what you learned' for more useful answers." },
  { id: 'longest-river', month: 1, day: 19, kind: 'fact', summary: "The Nile and the Amazon are both contenders for the world's longest river.", detailBody: "Different measurement methods and disputed source points mean the exact ranking is still debated among geographers — length isn't always as fixed a fact as it seems.\n\nFor teachers: A good example of how even 'settled' geography facts can involve real scientific debate." },
  { id: 'apollo-computer', month: 1, day: 20, kind: 'fact', summary: 'The 1969 Moon landing relied on computers far less powerful than a modern calculator.', detailBody: 'The Apollo Guidance Computer had about 4KB of memory — a testament to how much can be achieved with careful mathematics and engineering, not just raw computing power.\n\nFor teachers: Worth mentioning when discussing that clever problem-solving often matters more than having the newest tools.' },
  { id: 'divergent-thinking', month: 1, day: 21, kind: 'thought', summary: "Creativity is often about generating many possible answers, not finding the one 'right' one.", detailBody: "This is called divergent thinking, and it's a skill that can be practised — asking 'how many uses can you think of for a paperclip?' trains the same muscle as open-ended problem solving.\n\nClassroom idea: Occasionally ask for three possible answers to a question instead of one." },
  { id: 'saturn-rings', month: 1, day: 22, kind: 'fact', summary: "Saturn's rings are made mostly of ice, not rock.", detailBody: "They're composed of billions of small particles, most of them water ice, ranging from dust-sized grains to chunks the size of a house.\n\nFor teachers: A vivid detail when teaching the solar system beyond just planet order." },
  { id: 'bose-netaji', month: 1, day: 23, kind: 'fact', summary: '23 January marks the birth anniversary of freedom fighter Subhas Chandra Bose.', detailBody: 'Bose, known as "Netaji", was a prominent leader in India\'s independence movement and founder of the Indian National Army.\n\nFor teachers: A good moment to discuss how India\'s independence movement had many different leaders and strategies, not just one.' },
  { id: 'reading-vocabulary', month: 1, day: 24, kind: 'thought', summary: "Children who read for pleasure regularly encounter far more new words than those who don't.", detailBody: "Books, especially, use a wider and rarer vocabulary than everyday conversation or most television — reading volume is one of the strongest predictors of vocabulary growth.\n\nFor teachers: Worth remembering when encouraging independent reading, even a few pages a day." },
  { id: 'voters-day', month: 1, day: 25, kind: 'fact', summary: "25 January is National Voters' Day in India, marking the founding of the Election Commission in 1950.", detailBody: 'It aims to encourage young and newly eligible voters to register and understand their role in a democracy.\n\nFor teachers: Pairs naturally with Republic Day (26 January) for a short civics discussion.' },
  { id: 'place-value', month: 1, day: 26, kind: 'fact', summary: 'The position of a digit, not just the digit itself, gives a number its value.', detailBody: "This is the place-value system — the '3' in 300 means something completely different from the '3' in 30, purely because of its position.\n\nFor teachers: A concept worth revisiting whenever early learners struggle with multi-digit numbers." },
  { id: 'attachment-security', month: 1, day: 27, kind: 'thought', summary: "A child's sense of safety with trusted adults shapes how freely they explore and learn.", detailBody: 'When students feel secure with a teacher, they take more academic risks — asking questions, attempting hard problems, admitting confusion.\n\nFor teachers: Small consistent routines (a greeting, a check-in) do more for this than any single grand gesture.' },
  { id: 'penicillin', month: 1, day: 28, kind: 'fact', summary: 'Alexander Fleming discovered penicillin somewhat by accident, in 1928, from a contaminated petri dish.', detailBody: 'He noticed that mould growing on a forgotten culture plate was killing the bacteria around it — the first modern antibiotic followed from that observation.\n\nFor teachers: A good example of how careful observation of an "accident" can lead to a major discovery.' },
  { id: 'antarctica-desert', month: 1, day: 29, kind: 'fact', summary: 'The largest desert in the world is Antarctica, not the Sahara.', detailBody: 'A desert is defined by low precipitation, not heat — and Antarctica, though covered in ice, receives very little snowfall, making it technically the largest desert on Earth.\n\nFor teachers: A great example of how a scientific definition can overturn an everyday assumption.' },
  { id: 'martyrs-day', month: 1, day: 30, kind: 'fact', summary: "30 January is observed as Martyrs' Day in India, marking Mahatma Gandhi's death in 1948.", detailBody: "Schools and public offices across India observe two minutes of silence at 11 am on this day.\n\nFor teachers: A quiet, reflective day rather than a celebratory one — well suited to a short, respectful classroom moment rather than an activity." },
  { id: 'small-wins', month: 1, day: 31, kind: 'thought', summary: 'Recognising small, specific progress keeps motivation going better than waiting for a big milestone.', detailBody: "Large goals can feel distant and discouraging; noticing concrete small wins along the way keeps momentum alive, for students and teachers alike.\n\nAs January ends: one small win from this month is worth naming, even if the bigger goal is still far off." },
];

const FEB_FACTS: DailyFact[] = [
  { id: 'coral-reefs', month: 2, day: 1, kind: 'fact', summary: 'Coral reefs cover less than 1% of the ocean floor but support around a quarter of all marine species.', detailBody: 'Corals are actually tiny animals living in large colonies, not plants or rocks, despite how they look.\n\nFor teachers: A striking density statistic for teaching biodiversity and ecosystems.' },
  { id: 'varied-practice', month: 2, day: 2, kind: 'thought', summary: 'Practising a skill in varied contexts builds more flexible understanding than repeating one identical problem.', detailBody: "Practising the exact same problem repeatedly has limited benefit; practising the same skill through varied problems builds understanding that transfers more easily.\n\nClassroom idea: Vary the numbers, context, or format of practice problems rather than repeating identical ones." },
  { id: 'human-genome', month: 2, day: 3, kind: 'fact', summary: 'Humans share about 98–99% of their DNA with chimpanzees.', detailBody: "A tiny fraction of genetic difference accounts for major differences in brain size, language and tool use between the two species.\n\nFor teachers: A striking number when teaching that small genetic changes can have very large effects." },
  { id: 'world-cancer-day', month: 2, day: 4, kind: 'fact', summary: '4 February is World Cancer Day, an international day to raise awareness and support research.', detailBody: "It's observed by health organisations worldwide to encourage prevention, early detection and support for patients and families.\n\nFor teachers: A sensitive topic best introduced briefly and factually, with older students, rather than as a detailed classroom activity." },
  { id: 'metacognition', month: 2, day: 5, kind: 'thought', summary: 'Thinking about your own thinking — metacognition — is a skill that can be taught directly.', detailBody: "Students who pause to ask 'do I actually understand this, or does it just look familiar?' catch gaps earlier than those who don't.\n\nClassroom idea: After a lesson, ask students to rate their own understanding before you tell them the answer." },
  { id: 'plate-tectonics', month: 2, day: 6, kind: 'fact', summary: "Earth's continents are slowly moving — about as fast as fingernails grow.", detailBody: 'Plate tectonics causes continents to drift roughly 2–5 cm per year, driven by the slow churning of molten rock deep beneath the crust.\n\nFor teachers: A good way to make deep geological time feel more concrete — small annual movement, enormous cumulative effect.' },
  { id: 'binary-code', month: 2, day: 7, kind: 'fact', summary: 'All computer data — text, images, sound — is ultimately stored as sequences of 0s and 1s.', detailBody: 'This binary system works because electronic switches have only two reliable states: on and off — everything else is built up from there.\n\nFor teachers: A good simplification when introducing how computers "think" in a way that connects to place value in maths.' },
  { id: 'protege-effect', month: 2, day: 8, kind: 'thought', summary: 'Explaining a concept to someone else often reveals gaps in your own understanding.', detailBody: "This is sometimes called the 'protégé effect' — students who prepare to teach material learn it more thoroughly than those who just study it for a test.\n\nClassroom idea: Pair students to explain a concept to each other before you explain it yourself." },
  { id: 'ocean-unexplored', month: 2, day: 9, kind: 'fact', summary: "More than 80% of the world's oceans remain unmapped and unexplored.", detailBody: 'We have more detailed maps of the surface of Mars and the Moon than we do of our own ocean floor.\n\nFor teachers: A humbling fact for a geography or environmental science lesson — there\'s still a lot left to discover close to home.' },
  { id: 'active-learning', month: 2, day: 10, kind: 'thought', summary: 'Students remember more from doing something than from watching or listening to it.', detailBody: "This roughly matches the idea behind 'learning by doing' — hands-on practice, even brief, tends to stick better than passive observation alone.\n\nClassroom idea: If a demonstration works, a short hands-on follow-up usually helps more than a second demonstration." },
  { id: 'fibonacci-nature', month: 2, day: 11, kind: 'fact', summary: 'The Fibonacci sequence — where each number is the sum of the two before it — shows up throughout nature.', detailBody: 'Sunflower seed spirals, pinecone scales and nautilus shells all tend to follow Fibonacci-related patterns, since this growth pattern packs new elements efficiently.\n\nFor teachers: A great bridge between mathematics and biology — ask students to find the pattern in a real pinecone or seed head.' },
  { id: 'darwin-birthday', month: 2, day: 12, kind: 'fact', summary: '12 February marks the birthday of Charles Darwin, who proposed the theory of evolution by natural selection.', detailBody: 'Darwin\'s 1859 book "On the Origin of Species" reshaped how science understands the diversity of life on Earth.\n\nFor teachers: A good anchor date for introducing evolution, adaptation, or the idea that scientific theories are built on years of careful observation.' },
  { id: 'world-radio-day', month: 2, day: 13, kind: 'fact', summary: '13 February is World Radio Day, marking a technology that still reaches billions of people.', detailBody: 'Despite the rise of digital media, radio remains one of the most accessible ways to reach remote and low-connectivity communities, including for educational broadcasts.\n\nFor teachers: Worth mentioning when discussing how older technologies still serve purposes newer ones don\'t fully replace.' },
  { id: 'heart-beats', month: 2, day: 14, kind: 'fact', summary: 'The human heart beats about 100,000 times a day, pumping roughly 7,500 litres of blood.', detailBody: 'Over an average lifetime, that adds up to more than 2.5 billion heartbeats, all from a muscle roughly the size of a fist.\n\nFor teachers: A striking number to open a lesson on the circulatory system.' },
  { id: 'differentiated-instruction', month: 2, day: 15, kind: 'thought', summary: 'The same lesson can reach more students when it offers more than one path to the goal.', detailBody: "Differentiated instruction doesn't mean lowering the bar — it means offering different routes (visual, verbal, hands-on) to the same learning target.\n\nClassroom idea: For one lesson this week, offer students a choice in how they show what they've learned." },
  { id: 'russia-timezones', month: 2, day: 16, kind: 'fact', summary: 'Russia is so large that it spans 11 different time zones.', detailBody: "It's possible to fly for hours within a single country and still land in a place where the clock reads several hours different.\n\nFor teachers: A vivid way to make the size of the largest country on Earth concrete for students." },
  { id: 'robotics-manufacturing', month: 2, day: 17, kind: 'fact', summary: 'Industrial robots have been used on factory floors since the 1960s, long before robots became a common household idea.', detailBody: 'The first industrial robot, Unimate, was installed on a General Motors assembly line in 1961 to handle hot metal parts too dangerous for workers.\n\nFor teachers: Useful when discussing automation as a decades-long trend, not a brand-new phenomenon.' },
  { id: 'confirmation-bias', month: 2, day: 18, kind: 'thought', summary: 'People naturally notice information that confirms what they already believe, and overlook what doesn\'t.', detailBody: "This is called confirmation bias, and it affects experts and students alike — actively seeking out the opposite view is a learnable habit, not something that happens automatically.\n\nClassroom idea: When debating a topic, ask students to argue the side they disagree with first." },
  { id: 'shivaji-jayanti', month: 2, day: 19, kind: 'fact', summary: '19 February marks the birth anniversary of Chhatrapati Shivaji Maharaj, founder of the Maratha Empire.', detailBody: 'Shivaji is remembered for his administrative reforms and military strategy, and is widely commemorated, especially across Maharashtra.\n\nFor teachers: A good entry point into regional Indian history beyond the more commonly taught Mughal and colonial periods.' },
  { id: 'social-justice-day', month: 2, day: 20, kind: 'fact', summary: "20 February is the UN's World Day of Social Justice, focused on fair opportunity for all.", detailBody: 'It highlights issues like poverty, discrimination and unequal access to education and employment across the world.\n\nFor teachers: A fitting day for an age-appropriate discussion on fairness and equal opportunity in the classroom itself.' },
  { id: 'mother-language-day', month: 2, day: 21, kind: 'fact', summary: '21 February is International Mother Language Day, celebrating linguistic diversity worldwide.', detailBody: 'UNESCO established the day to promote awareness of the roughly 7,000 languages spoken globally, many of which are at risk of disappearing.\n\nFor teachers: Especially relevant in India\'s multilingual classrooms — a good day to celebrate the different home languages students bring in.' },
  { id: 'formative-assessment', month: 2, day: 22, kind: 'thought', summary: 'A quick check partway through a lesson is often more useful than a single big test at the end.', detailBody: "Formative assessment — short, low-stakes checks during learning — lets a teacher adjust course before misunderstandings harden into habits.\n\nClassroom idea: A one-question show-of-hands check mid-lesson can reveal confusion early enough to fix it." },
  { id: 'exoplanets', month: 2, day: 23, kind: 'fact', summary: 'Astronomers have confirmed the existence of more than 5,000 planets outside our solar system.', detailBody: "These 'exoplanets' are detected indirectly — often by measuring the tiny dip in a star's brightness as a planet passes in front of it.\n\nFor teachers: A good way to show that scientists can measure things they can't directly see, using careful indirect evidence." },
  { id: 'great-wall', month: 2, day: 24, kind: 'fact', summary: "The Great Wall of China isn't a single continuous wall, but a network of walls built over centuries.", detailBody: 'Different dynasties built and rebuilt sections over roughly 2,000 years, using different materials and methods depending on the region and era.\n\nFor teachers: A useful correction to the common oversimplified image of "one wall built at one time."' },
  { id: 'creative-constraints', month: 2, day: 25, kind: 'thought', summary: 'Constraints often boost creativity rather than limiting it.', detailBody: "Being told 'write a story in exactly six words' or 'design with only three colours' forces more inventive solutions than being given total freedom.\n\nClassroom idea: Add one deliberate constraint to your next open-ended assignment and see what it does to the results." },
  { id: 'infinite-primes', month: 2, day: 26, kind: 'fact', summary: 'There are infinitely many prime numbers — a fact proven by Euclid over 2,000 years ago.', detailBody: "Euclid's elegant proof shows that no matter how large a list of primes you have, you can always construct a new prime not on it.\n\nFor teachers: A good example of a simple, ancient proof that's still taught exactly as it was first written." },
  { id: 'play-based-learning', month: 2, day: 27, kind: 'thought', summary: "Play isn't the opposite of learning — for young children, it's one of the main ways learning happens.", detailBody: "Through play, children test cause and effect, practise social rules, and build language, all without it feeling like 'work.'\n\nFor teachers: Worth remembering with younger grades — a well-designed game can teach as much as a worksheet." },
  { id: 'science-day-india', month: 2, day: 28, kind: 'fact', summary: '28 February is National Science Day in India, marking the discovery of the Raman Effect.', detailBody: 'Physicist C.V. Raman announced his discovery on this date in 1928, later winning the Nobel Prize in Physics for it in 1930.\n\nFor teachers: A good day to highlight an Indian scientist whose work is still cited in physics and chemistry today.' },
  { id: 'leap-day', month: 2, day: 29, kind: 'fact', summary: "29 February exists because Earth's year is about 365.25 days long, not exactly 365.", detailBody: "Adding a leap day roughly every four years keeps our calendar aligned with Earth's orbit — without it, the seasons would slowly drift out of sync with the months over centuries.\n\nFor teachers: A neat, once-in-four-years hook for a lesson on time, orbits, and why calendars need occasional correction." },
];

const MAR_FACTS: DailyFact[] = [
  { id: 'rainbow-physics', month: 3, day: 1, kind: 'fact', summary: 'A rainbow forms when sunlight refracts and reflects inside raindrops, splitting into its full range of colours.', detailBody: 'Every rainbow you see is actually personal — someone standing a few metres away sees light from slightly different raindrops, so no two people ever see the exact same rainbow.\n\nFor teachers: A great optics demonstration using a simple prism or a garden hose in sunlight.' },
  { id: 'wait-time', month: 3, day: 2, kind: 'thought', summary: 'Waiting just three extra seconds after asking a question dramatically changes classroom responses.', detailBody: "Research on 'wait time' shows that pausing 3+ seconds before calling on a student leads to longer, more thoughtful answers and more students willing to raise their hands.\n\nTry this: count silently to three after asking a question before calling on anyone." },
  { id: 'world-wildlife-day', month: 3, day: 3, kind: 'fact', summary: '3 March is World Wildlife Day, marking the adoption of CITES, the treaty protecting endangered species.', detailBody: 'It celebrates the diversity of wild animals and plants while raising awareness of the threats they face from habitat loss and poaching.\n\nFor teachers: Pairs naturally with a lesson on ecosystems, food chains, or conservation.' },
  { id: 'mauna-kea', month: 3, day: 4, kind: 'fact', summary: "The tallest mountain measured from base to peak isn't Everest — it's Mauna Kea in Hawaii.", detailBody: "Everest has the highest elevation above sea level, but Mauna Kea rises about 10,200 metres from its base on the ocean floor — taller than Everest, just mostly underwater.\n\nFor teachers: A good example of how 'tallest' depends on exactly what you're measuring." },
  { id: 'cold-calling', month: 3, day: 5, kind: 'thought', summary: 'Calling on students at random, not just those with raised hands, keeps the whole class more engaged.', detailBody: "When only volunteers answer, the rest of the class can quietly disengage. Random or rotating selection (with fair warning) keeps everyone mentally in the game.\n\nClassroom idea: Try popsicle-stick or roll-number based calling for one lesson this week." },
  { id: 'plasma-state', month: 3, day: 6, kind: 'fact', summary: 'Plasma, not solid, liquid or gas, is actually the most common state of matter in the universe.', detailBody: 'Stars, including our Sun, are made of plasma — a hot, charged gas where electrons are stripped from atoms.\n\nFor teachers: A good fourth state to add once students are comfortable with solid, liquid and gas.' },
  { id: 'telephone-patent', month: 3, day: 7, kind: 'fact', summary: '7 March 1876 is the date Alexander Graham Bell was granted a patent for the telephone.', detailBody: "Bell's device converted sound into an electrical signal and back again — the same basic principle still underlies phone calls today, even digital ones.\n\nFor teachers: A good example of how a single invention can define an entire industry for over a century." },
  { id: 'marie-curie', month: 3, day: 8, kind: 'fact', summary: 'Marie Curie remains the only person to win Nobel Prizes in two different sciences — physics and chemistry.', detailBody: 'Her research on radioactivity (a term she coined) laid groundwork still used in medicine and physics today.\n\nFor teachers: A strong example to pair with any Women\'s Day discussion of women in science.' },
  { id: 'active-listening', month: 3, day: 9, kind: 'thought', summary: 'Listening to understand, rather than listening to reply, changes how a conversation goes.', detailBody: 'It\'s a small shift — pausing before responding, checking you understood before adding your own point — but it changes how safe people feel raising ideas.\n\nFor teachers: Modelling this in class discussions teaches it more effectively than explaining it.' },
  { id: 'green-sahara', month: 3, day: 10, kind: 'fact', summary: 'The Sahara Desert was green and covered in lakes and grassland as recently as 6,000 years ago.', detailBody: "Gradual shifts in Earth's orbit changed monsoon patterns over Africa, turning a fertile region into the world's largest hot desert.\n\nFor teachers: A striking example of how 'permanent' landscapes actually change over long timescales." },
  { id: 'correlation-causation', month: 3, day: 11, kind: 'thought', summary: "Two things happening together doesn't mean one caused the other.", detailBody: 'Ice cream sales and drowning incidents both rise in summer — not because ice cream causes drowning, but because both are driven by hot weather.\n\nClassroom idea: This is a reliable go-to example when teaching correlation versus causation.' },
  { id: 'dandi-march', month: 3, day: 12, kind: 'fact', summary: "12 March 1930 marks the start of Gandhi's Dandi March, a 24-day walk to protest the British salt tax.", detailBody: "The peaceful march became one of the most famous acts of civil disobedience in India's independence movement.\n\nFor teachers: A concrete example of non-violent protest as an organised strategy, not just a value in the abstract." },
  { id: 'wing-lift', month: 3, day: 13, kind: 'fact', summary: 'An aeroplane wing is shaped to make air move faster over the top than underneath, creating lift.', detailBody: 'This difference in air speed creates a pressure difference that pushes the wing — and the whole aircraft — upward.\n\nFor teachers: A good simplified explanation for younger grades; older students can explore the more complete aerodynamic picture.' },
  { id: 'pi-day', month: 3, day: 14, kind: 'fact', summary: '14 March is celebrated by many as Pi Day, since 3/14 matches the first digits of π (3.14).', detailBody: "Pi is the ratio of a circle's circumference to its diameter, and its digits continue infinitely without repeating.\n\nFor teachers: A fun, low-effort way to bring a smile to a maths lesson — even just writing out digits of π as a class challenge." },
  { id: 'specific-feedback', month: 3, day: 15, kind: 'thought', summary: "A short, specific note ('I liked how you explained step 2') can do more than a grade alone.", detailBody: "Grades tell a student where they stand; specific comments tell them what to do next — both matter, but only one is actionable.\n\nTry this: add one specific, actionable sentence to your next round of feedback." },
  { id: 'taste-vs-smell', month: 3, day: 16, kind: 'fact', summary: 'Most of what we perceive as "taste" actually comes from smell, not the tongue.', detailBody: "The tongue can only detect a handful of basic tastes (sweet, sour, salty, bitter, umami) — the rest of a food's flavour comes from aroma reaching the nose from inside the mouth.\n\nFor teachers: Easy to demonstrate — flavour differences are much harder to detect while holding your nose." },
  { id: 'active-volcanoes', month: 3, day: 17, kind: 'fact', summary: 'There are more than 1,500 active volcanoes on Earth, and around 50 erupt in a typical year.', detailBody: "Most eruptions are small and happen along the 'Ring of Fire' circling the Pacific Ocean, where tectonic plates meet.\n\nFor teachers: A good companion fact to plate tectonics lessons." },
  { id: 'context-clues', month: 3, day: 18, kind: 'thought', summary: 'Guessing an unfamiliar word from context is a skill that improves with deliberate practice.', detailBody: "Strong readers don't know every word — they're good at using surrounding sentences to infer meaning, then confirming later.\n\nClassroom idea: When a hard word comes up, ask 'what do you think it means, and why?' before giving the definition." },
  { id: 'mars-red', month: 3, day: 19, kind: 'fact', summary: 'Mars appears red because its surface is covered in iron oxide — essentially, rust.', detailBody: 'Iron-rich dust covering the Martian surface has oxidised over billions of years, giving the planet its distinctive colour.\n\nFor teachers: A good link between everyday chemistry (rusting) and something happening on another planet.' },
  { id: 'spring-equinox', month: 3, day: 20, kind: 'fact', summary: 'Around 20 March, day and night are roughly equal length across the whole planet — the spring equinox.', detailBody: "This happens because the Sun sits directly above the equator on this date, before continuing its apparent path north for the Northern Hemisphere's spring.\n\nFor teachers: Also International Day of Happiness and International Day of Forests — a good day to combine with a seasons lesson." },
  { id: 'forests-day', month: 3, day: 21, kind: 'fact', summary: '21 March is the International Day of Forests, marking the vital role trees play worldwide.', detailBody: "Forests are home to roughly 80% of the world's land-based animal and plant species and help regulate the global climate.\n\nFor teachers: A good day for an environmental science tie-in, even a short one." },
  { id: 'water-day', month: 3, day: 22, kind: 'fact', summary: '22 March is World Water Day, focused on the importance of freshwater and sustainable access to it.', detailBody: "Less than 1% of the world's water is fresh, accessible surface water — the rest is seawater, ice, or deep underground.\n\nFor teachers: A useful statistic when teaching water conservation or the water cycle." },
  { id: 'meteorological-day', month: 3, day: 23, kind: 'fact', summary: '23 March is World Meteorological Day, marking the founding of the World Meteorological Organization.', detailBody: 'It celebrates the science of weather forecasting, which today draws on satellites, ocean sensors and supercomputers to predict conditions days in advance.\n\nFor teachers: A good hook into how weather forecasting actually works, beyond just checking an app.' },
  { id: 'ramanujan-early', month: 3, day: 24, kind: 'fact', summary: 'Mathematician Srinivasa Ramanujan had almost no formal training yet independently discovered results that had taken Western mathematicians centuries.', detailBody: 'Ramanujan sent his notebooks to Cambridge mathematician G.H. Hardy in 1913, beginning one of the most remarkable collaborations in the history of mathematics.\n\nFor teachers: A powerful example that mathematical talent isn\'t limited to formal institutions or privilege.' },
  { id: 'zone-proximal-development', month: 3, day: 25, kind: 'thought', summary: 'Give a student just slightly more than they can do alone, with support, and they grow fastest.', detailBody: "This 'zone of proximal development' idea suggests the best learning happens just beyond a student's current ability, with the right amount of guidance — not too easy, not too hard.\n\nFor teachers: A useful lens when a task feels 'too easy' or 'too hard' for most of the class." },
  { id: 'qwerty-history', month: 3, day: 26, kind: 'fact', summary: 'The QWERTY keyboard layout was designed to prevent mechanical typewriters from jamming, not for typing speed.', detailBody: "Common letter pairs were deliberately spread apart so the metal arms of early typewriters wouldn't collide — a 19th-century engineering fix we still type on today.\n\nFor teachers: A good example of how old technical constraints can outlive the problem that created them." },
  { id: 'theatre-day', month: 3, day: 27, kind: 'fact', summary: "27 March is World Theatre Day, celebrating live performance as one of humanity's oldest art forms.", detailBody: 'Theatre traditions stretch back thousands of years, from ancient Greek drama to classical Indian forms like Kathakali and Yakshagana.\n\nFor teachers: A good day for a short role-play or reading-aloud activity in any subject.' },
  { id: 'idea-generation', month: 3, day: 28, kind: 'thought', summary: 'Separating idea generation from idea evaluation produces better ideas overall.', detailBody: "Judging ideas as they're proposed makes people cautious and less willing to suggest anything unusual — a 'no judgment' brainstorming round first tends to surface more, and better, options.\n\nClassroom idea: Collect all ideas silently first, then evaluate as a separate second step." },
  { id: 'waggle-dance', month: 3, day: 29, kind: 'fact', summary: "Honeybees communicate the direction and distance of food using a 'waggle dance.'", detailBody: "The angle and duration of the dance tell other bees exactly where to find flowers relative to the sun's position — a remarkably precise form of animal communication.\n\nFor teachers: A great example that complex communication isn't limited to humans." },
  { id: 'multilingual-asset', month: 3, day: 30, kind: 'thought', summary: 'Speaking more than one language is an academic asset, not a distraction from learning.', detailBody: 'Research generally finds that bilingual and multilingual students often show strengths in flexible thinking and problem solving, not confusion between languages.\n\nFor teachers: Worth remembering in multilingual Indian classrooms — a student\'s home language is a resource, not an obstacle.' },
  { id: 'eiffel-expansion', month: 3, day: 31, kind: 'fact', summary: 'The Eiffel Tower grows about 15 cm taller in summer, as the iron structure expands in the heat.', detailBody: 'This thermal expansion is the same basic physics that causes railway tracks to need small gaps, and bridges to include expansion joints.\n\nFor teachers: A fun everyday example of thermal expansion beyond a textbook diagram.' },
];

const APR_FACTS: DailyFact[] = [
  { id: 'trillion-cells', month: 4, day: 1, kind: 'fact', summary: 'The average adult human body contains about 37 trillion cells.', detailBody: 'Each of those cells carries a nearly complete copy of your DNA, coordinated well enough to keep a single organism (you) functioning as one whole.\n\nFor teachers: A good number to open a biology unit on cells.' },
  { id: 'think-pair-share', month: 4, day: 2, kind: 'thought', summary: 'Giving students a moment to think alone before discussing in pairs improves group discussion quality.', detailBody: "Jumping straight to group discussion often means the fastest thinker dominates. A short 'think' step first gives quieter students something ready to contribute.\n\nClassroom idea: Try 'think for 30 seconds, then turn to your partner' before your next class discussion." },
  { id: 'lake-baikal', month: 4, day: 3, kind: 'fact', summary: 'Lake Baikal in Russia holds about 20% of the world\'s unfrozen fresh water — more than all five North American Great Lakes combined.', detailBody: "It's also the world's deepest lake, reaching depths of over 1,600 metres.\n\nFor teachers: A good corrective to the assumption that the biggest-looking lake always holds the most water." },
  { id: 'venus-hottest', month: 4, day: 4, kind: 'fact', summary: 'Venus is the hottest planet in the solar system, even hotter than Mercury, which is closer to the Sun.', detailBody: "Venus's thick carbon-dioxide atmosphere traps heat in a runaway greenhouse effect, pushing surface temperatures above 460°C.\n\nFor teachers: A good example that 'closest to the Sun' and 'hottest' aren't automatically the same thing." },
  { id: 'spacing-effect', month: 4, day: 5, kind: 'thought', summary: 'Spreading study sessions out over several days works better than one long cram session.', detailBody: "This 'spacing effect' is one of the most consistently replicated findings in learning research — revisiting material after a gap strengthens memory more than repeating it immediately.\n\nFor teachers: Worth explaining directly to older students before exam season, since it goes against most people's instinct to cram." },
  { id: 'banana-berry', month: 4, day: 6, kind: 'fact', summary: 'Bananas are botanically classified as berries, while strawberries are not.', detailBody: "Botanically, a berry must develop from a single flower with one ovary — bananas qualify, but strawberries (and raspberries) technically don't.\n\nFor teachers: A fun example that everyday categories and scientific categories don't always match." },
  { id: 'world-health-day', month: 4, day: 7, kind: 'fact', summary: '7 April is World Health Day, marking the founding of the World Health Organization in 1948.', detailBody: 'Each year the day highlights a different global health priority, from mental health to universal access to care.\n\nFor teachers: A good, age-appropriate day to discuss basic health habits with younger students.' },
  { id: 'think-aloud-modeling', month: 4, day: 8, kind: 'thought', summary: 'Showing your own thinking out loud teaches students how to think, not just what to think.', detailBody: 'When a teacher solves a problem while narrating their reasoning — including false starts — students see the thinking process, not just a clean final answer.\n\nClassroom idea: Deliberately narrate one "wrong turn" while solving a problem, then show how you noticed and corrected it.' },
  { id: 'gps-relativity', month: 4, day: 9, kind: 'fact', summary: "GPS satellites have to correct for Einstein's theory of relativity to stay accurate.", detailBody: "Clocks on GPS satellites run faster than clocks on Earth due to weaker gravity and orbital speed — without correcting for this, GPS positions would drift by kilometres within a day.\n\nFor teachers: A striking real-world use of a theory some students assume is 'just abstract physics.'" },
  { id: 'googol', month: 4, day: 10, kind: 'fact', summary: "A 'googol' is the number 1 followed by 100 zeros — and it's smaller than the number of possible chess games.", detailBody: 'The term inspired the name of the company Google, though spelled differently, as a nod to organising a seemingly limitless amount of information.\n\nFor teachers: A fun way to make very large numbers feel more concrete.' },
  { id: 'rephrase-check', month: 4, day: 11, kind: 'thought', summary: 'Rephrasing what someone said, in your own words, is one of the fastest ways to check you understood them.', detailBody: "This is a core communication skill worth teaching directly: 'so what you're saying is...' catches misunderstandings before they cause problems.\n\nClassroom idea: Use this technique yourself when a student's answer is unclear, before correcting it." },
  { id: 'gagarin-spaceflight', month: 4, day: 12, kind: 'fact', summary: '12 April 1961 marks the day Yuri Gagarin became the first human to travel into space.', detailBody: 'His orbital flight lasted 108 minutes and marked the start of the era of human spaceflight.\n\nFor teachers: A good anchor date for a space-race era history lesson alongside the 1969 Moon landing.' },
  { id: 'octopus-blood', month: 4, day: 13, kind: 'fact', summary: 'An octopus has three hearts and blue-coloured blood.', detailBody: 'Two hearts pump blood to the gills, and a third pumps it to the rest of the body; the blue colour comes from a copper-based molecule instead of the iron-based one in human blood.\n\nFor teachers: A great example that not all animals are built the way we might assume.' },
  { id: 'equals-sign', month: 4, day: 14, kind: 'fact', summary: "The equals sign (=) was invented in 1557 by Welsh mathematician Robert Recorde, who was tired of writing 'is equal to' repeatedly.", detailBody: "He chose two parallel lines because, in his words, 'no two things can be more equal.'\n\nFor teachers: A fun reminder that even basic maths notation has a specific human history." },
  { id: 'mastery-goals', month: 4, day: 15, kind: 'thought', summary: 'Aiming to understand a topic tends to build more lasting motivation than aiming only to beat a score.', detailBody: "'Mastery goals' (get better at this) tend to sustain effort through setbacks better than 'performance goals' (score higher than others), which can collapse after one bad result.\n\nFor teachers: Framing feedback around growth in understanding, not just marks, supports this shift." },
  { id: 'world-voice-day', month: 4, day: 16, kind: 'fact', summary: '16 April is World Voice Day, celebrating the human voice and encouraging good vocal health.', detailBody: 'Teachers, who rely on their voice for hours daily, are especially prone to vocal strain — projecting from the diaphragm rather than the throat helps reduce it.\n\nFor teachers: A good day to actually rest your voice a little, if the schedule allows.' },
  { id: 'fresh-water-scarcity', month: 4, day: 17, kind: 'fact', summary: "Only about 3% of Earth's water is fresh water, and most of that is locked in glaciers and ice caps.", detailBody: "Less than 1% of all water on Earth is easily accessible fresh water — in rivers, lakes and shallow groundwater.\n\nFor teachers: Pairs well with World Water Day (22 March) if you want a two-part water unit." },
  { id: 'world-heritage-day', month: 4, day: 18, kind: 'fact', summary: '18 April is World Heritage Day, celebrating monuments and sites of historical and cultural importance.', detailBody: 'India alone has over 40 UNESCO World Heritage Sites, from the Taj Mahal to the Sundarbans mangrove forest.\n\nFor teachers: A good day to ask students to research one heritage site near their own city or state.' },
  { id: 'source-evaluation', month: 4, day: 19, kind: 'thought', summary: 'Before believing a claim, it helps to ask who is saying it and what they might gain from you believing it.', detailBody: "This single habit — checking the source and its possible motive — catches a surprising amount of misleading information before it needs fact-checking at all.\n\nClassroom idea: Practice this with two different sources reporting the same event." },
  { id: 'chess-combinatorics', month: 4, day: 20, kind: 'fact', summary: 'There are more possible unique chess games than atoms in the observable universe.', detailBody: 'The number of possible chess games is estimated to be around 10^120 — a number so large that even powerful computers can\'t brute-force every possibility.\n\nFor teachers: A vivid way to introduce exponential growth in a maths lesson.' },
  { id: 'civil-services-day', month: 4, day: 21, kind: 'fact', summary: '21 April is Civil Services Day in India, honouring public servants and their role in nation-building.', detailBody: "The day marks Sardar Vallabhbhai Patel's 1947 address to newly recruited civil servants, often called the 'steel frame' of India's administration.\n\nFor teachers: A good link when discussing how a country actually runs day to day, beyond just its elected leaders." },
  { id: 'earth-day', month: 4, day: 22, kind: 'fact', summary: '22 April is Earth Day, marked by millions of people worldwide with environmental action and awareness events.', detailBody: 'First observed in 1970, it\'s credited with helping build momentum for early environmental protection laws in several countries.\n\nFor teachers: A natural day for a class clean-up activity, tree-planting, or a discussion on local environmental issues.' },
  { id: 'world-book-day', month: 4, day: 23, kind: 'fact', summary: '23 April is World Book and Copyright Day, chosen partly because it marks the death of both Shakespeare and Cervantes.', detailBody: 'UNESCO created the day to promote reading, publishing, and the protection of intellectual property through copyright.\n\nFor teachers: A good day to highlight independent reading, a class library corner, or a favourite-book share.' },
  { id: 'rereading-fluency', month: 4, day: 24, kind: 'thought', summary: "Rereading a familiar book isn't a waste of time for a developing reader — it builds fluency and confidence.", detailBody: 'Reading the same text multiple times reduces the effort spent decoding words, freeing up attention for comprehension and expression.\n\nFor teachers: Worth reassuring parents who worry their child "just keeps rereading the same book."' },
  { id: 'malaria-day', month: 4, day: 25, kind: 'fact', summary: "25 April is World Malaria Day, raising awareness of a disease that remains a major public health challenge in many countries, including parts of India.", detailBody: 'Simple preventive measures like mosquito nets have significantly reduced malaria deaths worldwide over the past two decades.\n\nFor teachers: A good tie-in for a lesson on public health, mosquitoes, or disease prevention — factual, not alarming.' },
  { id: 'intellectual-property-day', month: 4, day: 26, kind: 'fact', summary: '26 April is World Intellectual Property Day, marking how patents, copyrights and trademarks protect creative and inventive work.', detailBody: "It's the same legal idea that protects a novelist's book, a scientist's patented invention, and a company's logo, all under different specific rules.\n\nFor teachers: A good hook when discussing plagiarism and why crediting original sources actually matters." },
  { id: 'executive-function', month: 4, day: 27, kind: 'thought', summary: "Skills like planning, focus and self-control develop gradually through childhood — they're not simply 'good behaviour' a child either has or doesn't.", detailBody: "These 'executive function' skills are like a muscle that strengthens with practice and consistent routine, not a fixed trait.\n\nFor teachers: Worth remembering when a young student seems to 'forget' instructions — the skill may still be developing, not absent." },
  { id: 'safety-at-work-day', month: 4, day: 28, kind: 'fact', summary: '28 April is the World Day for Safety and Health at Work, observed by the International Labour Organization.', detailBody: 'It highlights the importance of safe working conditions across all professions, from factories to classrooms.\n\nFor teachers: A good reminder that safety habits — fire drills, lab safety rules — are worth practising, not just posting on a wall.' },
  { id: 'international-dance-day', month: 4, day: 29, kind: 'fact', summary: '29 April is International Dance Day, celebrating dance as a universal form of expression across every culture.', detailBody: 'From Bharatanatyam to ballet, dance traditions across the world share the same basic idea: using movement to tell a story or express emotion.\n\nFor teachers: A fun cross-curricular link between physical education, art and cultural studies.' },
  { id: 'engineering-mindset', month: 4, day: 30, kind: 'thought', summary: "Engineers don't expect a first design to work — they expect to test, fail, and improve it.", detailBody: "This 'iterative design' mindset treats failure as data, not defeat: a design that doesn't work yet teaches you something the next attempt can use.\n\nClassroom idea: Frame a project's first draft explicitly as 'version 1', with revision expected, not optional." },
];

const MAY_FACTS: DailyFact[] = [
  { id: 'workers-day', month: 5, day: 1, kind: 'fact', summary: "1 May is International Workers' Day, honouring the labour movement and workers' rights worldwide.", detailBody: 'It commemorates the 1886 Haymarket affair in Chicago, part of the campaign for an eight-hour work day.\n\nFor teachers: A good entry point into a broader discussion of how workplace rights have changed over time.' },
  { id: 'australia-continent', month: 5, day: 2, kind: 'fact', summary: "Australia is both a country and a continent — the only place on Earth that's both.", detailBody: "It's the smallest continent by land area but the sixth-largest country, and it's the only continent governed by a single nation.\n\nFor teachers: A good 'this doesn't fit the usual pattern' geography fact." },
  { id: 'press-freedom-day', month: 5, day: 3, kind: 'fact', summary: '3 May is World Press Freedom Day, marking the importance of a free press in a functioning democracy.', detailBody: 'It was established by the UN in 1993 to highlight both the value of press freedom and the risks journalists face in reporting the truth.\n\nFor teachers: A good day to discuss reliable news sources with older students.' },
  { id: 'interleaved-practice', month: 5, day: 4, kind: 'thought', summary: 'Mixing up the order of topics in practice builds more flexible understanding than practising one topic at a time.', detailBody: 'Blocked practice (all of topic A, then all of topic B) feels easier during practice, but interleaved practice (mixing A and B) produces better long-term learning, even though it feels harder in the moment.\n\nClassroom idea: Mix a few review questions from last week into today\'s practice set.' },
  { id: 'proxima-centauri', month: 5, day: 5, kind: 'fact', summary: 'The star closest to our Sun, Proxima Centauri, is still about 4.2 light-years away.', detailBody: 'Even travelling at the speed of the fastest spacecraft ever built, it would take tens of thousands of years to get there.\n\nFor teachers: A good way to convey just how empty and vast space actually is between stars.' },
  { id: 'vatican-smallest', month: 5, day: 6, kind: 'fact', summary: 'Vatican City is the smallest country in the world, both by area and population.', detailBody: "At about 0.44 square kilometres, it's smaller than most public parks, yet it's a fully independent state with its own postal system and currency.\n\nFor teachers: A fun size-comparison fact for a geography lesson on countries and borders." },
  { id: 'tagore-birthday', month: 5, day: 7, kind: 'fact', summary: '7 May marks the birth anniversary of Rabindranath Tagore, the first non-European to win the Nobel Prize in Literature (1913).', detailBody: 'Tagore composed the national anthems of both India and Bangladesh, and founded Visva-Bharati University based on his own progressive ideas about education.\n\nFor teachers: Worth mentioning that Tagore\'s educational philosophy favoured nature, creativity and open-air learning over rote instruction.' },
  { id: 'self-efficacy', month: 5, day: 8, kind: 'thought', summary: "Believing you're capable of improving at something is often what determines whether you actually try.", detailBody: "This is 'self-efficacy' — students who believe effort can improve their ability tend to persist through difficulty far more than equally capable students who don't.\n\nFor teachers: Small early wins on manageable tasks help build this belief before tackling harder ones." },
  { id: 'email-predates-web', month: 5, day: 9, kind: 'fact', summary: 'Email predates the World Wide Web by about two decades.', detailBody: "The first email-like message was sent in 1971, while the Web wasn't invented until 1989 — a reminder that the internet grew in layers over a long period.\n\nFor teachers: Useful when explaining that 'the internet' is not one single invention with one single starting date." },
  { id: 'chess-seconds-universe', month: 5, day: 10, kind: 'fact', summary: 'A single game of chess has more possible move sequences than seconds have passed since the universe began.', detailBody: 'This is why even powerful computers rely on pattern recognition and strategy, not just checking every possible move, to play well.\n\nFor teachers: A good companion to the earlier "more chess games than atoms" fact when discussing very large numbers.' },
  { id: 'national-technology-day', month: 5, day: 11, kind: 'fact', summary: '11 May is National Technology Day in India, celebrating scientific and technological achievement.', detailBody: 'The day encourages recognition of Indian innovation across fields from space research to renewable energy.\n\nFor teachers: A good day to highlight a student project or a local example of applied science.' },
  { id: 'apollo-footprints', month: 5, day: 12, kind: 'fact', summary: "The footprints left by Apollo astronauts on the Moon could last millions of years.", detailBody: "With no wind, rain or atmosphere to erode them, there's nothing on the Moon to disturb marks left in its dust.\n\nFor teachers: A good detail for contrasting Earth's active weathering with the Moon's stillness." },
  { id: 'idea-combination', month: 5, day: 13, kind: 'thought', summary: 'Many creative breakthroughs come from combining two existing ideas in a new way, not inventing something from nothing.', detailBody: "The printing press combined an existing wine-press mechanism with movable type — a good reminder that 'new' ideas are often unusual combinations of old ones.\n\nClassroom idea: Ask students to combine two unrelated objects or ideas into one new invention as a quick creativity exercise." },
  { id: 'crow-cognition', month: 5, day: 14, kind: 'fact', summary: "A group of crows is called a 'murder,' and crows are known for remarkably sharp memory and problem-solving.", detailBody: 'Crows are among the most intelligent birds — they can recognise individual human faces and even pass that recognition on to other crows.\n\nFor teachers: A fun animal-behaviour fact that surprises most students.' },
  { id: 'international-families-day', month: 5, day: 15, kind: 'fact', summary: '15 May is the International Day of Families, recognising the family\'s role in education and wellbeing.', detailBody: "It's a reminder that a child's learning happens across school and home together, not in one place alone.\n\nFor teachers: A good day to send a positive note home, if only briefly." },
  { id: 'bee-face-recognition', month: 5, day: 16, kind: 'fact', summary: 'Honeybees can recognise human faces, using a similar visual strategy to how humans do.', detailBody: 'Despite having a brain the size of a grass seed, bees can be trained to associate specific human faces with a reward.\n\nFor teachers: A nice pairing with the earlier waggle-dance fact when discussing animal cognition.' },
  { id: 'telecommunication-day', month: 5, day: 17, kind: 'fact', summary: '17 May is World Telecommunication and Information Society Day, marking the anniversary of the International Telecommunication Union.', detailBody: 'It celebrates how communication technology, from the telegraph to mobile internet, has reshaped how the world shares information.\n\nFor teachers: A good link when discussing how technology has changed the speed of communication over generations.' },
  { id: 'museum-day', month: 5, day: 18, kind: 'fact', summary: '18 May is International Museum Day, celebrating museums as spaces for learning, culture and preservation.', detailBody: "Museums aren't just for history — science centres, art galleries and even digital museums all count, offering hands-on learning outside a classroom.\n\nFor teachers: A good prompt for a virtual museum tour if an in-person field trip isn't possible." },
  { id: 'worked-examples', month: 5, day: 19, kind: 'thought', summary: 'Showing a fully worked example before asking students to try alone reduces frustration without reducing learning.', detailBody: 'This is especially effective for brand-new types of problems — once students have practised, gradually removing the worked example (fading) keeps the challenge appropriate.\n\nClassroom idea: For a new problem type, show one complete worked example before the first independent attempt.' },
  { id: 'world-bee-day', month: 5, day: 20, kind: 'fact', summary: '20 May is World Bee Day, recognising the vital role bees and other pollinators play in food production.', detailBody: 'About one in three bites of food humans eat depends on pollinators like bees, in crops ranging from apples to almonds.\n\nFor teachers: A strong hook for an ecosystems or food-chain lesson.' },
  { id: 'cultural-diversity-day', month: 5, day: 21, kind: 'fact', summary: '21 May is the World Day for Cultural Diversity for Dialogue and Development.', detailBody: 'It recognises that cultural diversity is a source of exchange, innovation and creativity — not simply a fact to be tolerated.\n\nFor teachers: A fitting day to celebrate the range of backgrounds and traditions represented within your own classroom.' },
  { id: 'biological-diversity-day', month: 5, day: 22, kind: 'fact', summary: '22 May is the International Day for Biological Diversity, marking the adoption of the Convention on Biological Diversity in 1992.', detailBody: 'Biodiversity loss is now recognised as being as serious a global challenge as climate change, since ecosystems rely on variety to stay resilient.\n\nFor teachers: Pairs well with a local nature walk or a simple biodiversity count in a school garden.' },
  { id: 'autonomy-motivation', month: 5, day: 23, kind: 'thought', summary: 'Giving students small, genuine choices increases motivation more than most people expect.', detailBody: 'Choosing which of two problems to solve first, or which format to present work in, is a small amount of control — but it consistently increases engagement compared to no choice at all.\n\nClassroom idea: Offer a choice between two equivalent task formats this week and notice the difference in engagement.' },
  { id: 'mona-lisa-eyebrows', month: 5, day: 24, kind: 'fact', summary: 'The "Mona Lisa" has no eyebrows — a detail more accidental than deliberate, most historians believe.', detailBody: "Some art historians think Leonardo da Vinci simply hadn't finished the painting when he died; others believe fashion of the era favoured plucked or thin eyebrows.\n\nFor teachers: A fun example that not every historical mystery has a confirmed answer." },
  { id: 'africa-day', month: 5, day: 25, kind: 'fact', summary: '25 May is Africa Day, marking the founding of the Organisation of African Unity in 1963.', detailBody: 'Africa is home to 54 recognised countries and over 2,000 languages — a level of diversity often flattened in how the continent gets discussed.\n\nFor teachers: A good corrective moment when teaching world geography — Africa is a continent of countries, not a single place.' },
  { id: 'reading-aloud-benefits', month: 5, day: 26, kind: 'thought', summary: 'Reading aloud to students, even older ones, still measurably helps their vocabulary and listening comprehension.', detailBody: "It's not just for early learners — hearing fluent, expressive reading models pacing, tone and inference in a way silent reading alone doesn't teach.\n\nClassroom idea: A short daily read-aloud, even five minutes, adds up meaningfully over a term." },
  { id: 'light-year-distance', month: 5, day: 27, kind: 'fact', summary: "A 'light-year' measures distance, not time — despite the name.", detailBody: 'It\'s the distance light travels in one year: roughly 9.46 trillion kilometres, used because ordinary distance units become unwieldy at astronomical scales.\n\nFor teachers: A common student misconception worth addressing directly and early.' },
  { id: 'leap-second', month: 5, day: 28, kind: 'fact', summary: "A 'leap second' is occasionally added to clocks to keep them in sync with Earth's slightly irregular rotation.", detailBody: "Earth's spin isn't perfectly constant, so scientists occasionally insert an extra second into official time to keep clocks matched to the planet's actual rotation.\n\nFor teachers: A nice companion to the leap-year fact (29 February) on why calendars and clocks need occasional correction." },
  { id: 'everest-summit', month: 5, day: 29, kind: 'fact', summary: '29 May 1953 marks the first confirmed summit of Mount Everest, by Edmund Hillary and Tenzing Norgay.', detailBody: 'Tenzing Norgay, a Nepali-Indian Sherpa mountaineer, played as crucial a role in the historic climb as Hillary did, though he received less early recognition.\n\nFor teachers: A good moment to highlight often under-credited contributors to famous achievements.' },
  { id: 'routine-security', month: 5, day: 30, kind: 'thought', summary: 'Predictable routines help children feel secure enough to take academic risks.', detailBody: "Knowing roughly what to expect in a school day frees up a child's attention for learning, rather than for figuring out what happens next.\n\nFor teachers: Worth remembering that even small routine disruptions can affect younger students' focus more than adults expect." },
  { id: 'no-tobacco-day', month: 5, day: 31, kind: 'fact', summary: '31 May is World No Tobacco Day, an annual WHO campaign highlighting the health risks of tobacco use.', detailBody: 'It\'s one of the longest-running global public health awareness campaigns, first observed in 1987.\n\nFor teachers: Best handled briefly and factually with older students, as part of a broader health-awareness discussion.' },
];

const JUN_FACTS: DailyFact[] = [
  { id: 'global-parents-day', month: 6, day: 1, kind: 'fact', summary: "1 June is the UN's Global Day of Parents, recognising the role of parents in raising and educating children.", detailBody: "It's a companion to the International Day of Families (15 May), both underlining that a child's education is a shared effort.\n\nFor teachers: A good day to acknowledge parents in a newsletter or note home." },
  { id: 'great-barrier-reef', month: 6, day: 2, kind: 'fact', summary: 'The Great Barrier Reef is the largest living structure on Earth, visible even from space.', detailBody: "It stretches over 2,300 km along Australia's coast and is actually made up of nearly 3,000 individual reefs, not one continuous structure.\n\nFor teachers: A good scale comparison when discussing human-made vs natural structures." },
  { id: 'world-bicycle-day', month: 6, day: 3, kind: 'fact', summary: '3 June is World Bicycle Day, recognising the bicycle as a simple, sustainable form of transport.', detailBody: 'Bicycles remain one of the most energy-efficient forms of transport ever invented, converting a very high share of human energy into forward motion.\n\nFor teachers: A good physics tie-in on efficiency and simple machines.' },
  { id: 'octopus-nine-brains', month: 6, day: 4, kind: 'fact', summary: 'Octopuses have nine brains — one central brain and one smaller one in each of their eight arms.', detailBody: 'This lets each arm act semi-independently, solving simple problems (like opening a jar) even without direct signals from the central brain.\n\nFor teachers: A great companion to the earlier three-hearts octopus fact (13 April).' },
  { id: 'rainforest-biodiversity', month: 6, day: 5, kind: 'fact', summary: "Tropical rainforests are home to more than half of the world's known plant and animal species, despite covering only about 6% of Earth's land.", detailBody: 'This makes them one of the most biodiversity-dense ecosystems on the planet, and a major reason for global conservation efforts.\n\nFor teachers: A good, verified biodiversity statistic to use for an ecosystems lesson.' },
  { id: 'ask-dont-assume', month: 6, day: 6, kind: 'thought', summary: 'Asking a student what they meant is usually more useful than assuming you already know.', detailBody: 'A quick "tell me more about that" often reveals reasoning that looks wrong on the surface but makes complete sense once explained.\n\nClassroom idea: Before marking an unusual answer wrong, ask the student to walk you through their thinking.' },
  { id: 'qr-code-origin', month: 6, day: 7, kind: 'fact', summary: 'QR codes were invented in Japan in 1994 to track car parts during manufacturing.', detailBody: 'They can hold far more information than a standard barcode, which is why they were quickly adopted for far broader everyday uses, from menus to payments.\n\nFor teachers: A good example of a technology outgrowing its original narrow purpose.' },
  { id: 'world-oceans-day', month: 6, day: 8, kind: 'fact', summary: "8 June is World Oceans Day, highlighting the ocean's role in climate, food and daily life.", detailBody: 'The ocean produces more than half of the world\'s oxygen and absorbs a large share of the carbon dioxide humans produce.\n\nFor teachers: A good complement to any lesson on the water cycle or climate.' },
  { id: 'anecdote-persuasion', month: 6, day: 9, kind: 'thought', summary: 'A single vivid example can feel more convincing than a mountain of statistics — even when it shouldn\'t.', detailBody: 'This is why one dramatic story can outweigh solid data in people\'s minds; being aware of this bias is the first step to resisting it.\n\nClassroom idea: When a strong opinion is based on one example, ask "is this typical, or is this one unusual case?"' },
  { id: 'venus-day-year', month: 6, day: 10, kind: 'fact', summary: 'A day on Venus is longer than a year on Venus.', detailBody: 'Venus rotates so slowly that it takes about 243 Earth days to spin once, but only about 225 Earth days to orbit the Sun.\n\nFor teachers: A genuinely surprising planetary fact that gets students to double-check their assumptions.' },
  { id: 'banana-consumption', month: 6, day: 11, kind: 'fact', summary: "Bananas, not apples, are the world's most-consumed fruit by volume.", detailBody: 'Global banana production is enormous partly because they\'re grown and eaten year-round in many tropical countries, including India, one of the largest producers.\n\nFor teachers: A good link to a geography or economics lesson on global agriculture.' },
  { id: 'child-labour-day', month: 6, day: 12, kind: 'fact', summary: "12 June is the World Day Against Child Labour, marking the importance of every child's right to education instead of work.", detailBody: "It's led by the International Labour Organization to raise awareness of the millions of children worldwide still out of school due to labour.\n\nFor teachers: A meaningful, if serious, day to discuss why access to education is a right, not a given, for every child." },
  { id: 'chunking-information', month: 6, day: 13, kind: 'thought', summary: 'Breaking a large task into smaller labelled steps reduces overwhelm without reducing rigour.', detailBody: 'Working memory can only hold a few items at once — chunking a big task into clearly labelled steps respects that limit instead of fighting it.\n\nClassroom idea: For a multi-step task, list the steps explicitly rather than describing the whole task in one paragraph.' },
  { id: 'blood-donor-day', month: 6, day: 14, kind: 'fact', summary: '14 June is World Blood Donor Day, thanking voluntary blood donors and encouraging safe blood supplies worldwide.', detailBody: 'A single blood donation can potentially help save more than one life, since blood is often separated into multiple components for different patients.\n\nFor teachers: A good, factual way to introduce the circulatory system with a real-world civic angle for older students.' },
  { id: 'recite-vs-apply', month: 6, day: 15, kind: 'thought', summary: 'Being able to recite a rule and being able to apply it are two different skills, and only one predicts real understanding.', detailBody: 'A student who can state a formula perfectly but freezes when the question is phrased differently likely has memorised the words, not the concept.\n\nFor teachers: Worth checking for directly — ask the same concept in an unfamiliar format occasionally.' },
  { id: 'jellyfish-immortality', month: 6, day: 16, kind: 'fact', summary: 'A jellyfish has no brain, heart or bones, yet the group has survived for over 500 million years.', detailBody: "Some jellyfish species are even biologically 'immortal,' able to revert to an earlier life stage instead of dying of old age under the right conditions.\n\nFor teachers: A striking example that complexity isn't the only path to evolutionary success." },
  { id: 'desertification-day', month: 6, day: 17, kind: 'fact', summary: '17 June is the World Day to Combat Desertification and Drought.', detailBody: 'Desertification — fertile land turning barren — affects large parts of the world, driven by a mix of climate change and unsustainable land use.\n\nFor teachers: A good, concrete example when teaching human impact on ecosystems.' },
  { id: 'boredom-creativity', month: 6, day: 18, kind: 'thought', summary: 'Boredom, uncomfortable as it feels, often precedes a burst of creative thinking.', detailBody: "When the brain isn't given constant stimulation, it tends to wander and make unusual connections — some psychologists link idle time directly to creative problem-solving.\n\nFor teachers: Worth remembering before filling every single minute of unstructured time with structured activity." },
  { id: 'eye-colour-range', month: 6, day: 19, kind: 'fact', summary: 'The human eye can distinguish about 10 million different colours.', detailBody: 'This range comes from just three types of colour-sensing cells in the retina, combined in different proportions — remarkably efficient design for that much variety.\n\nFor teachers: A good link when teaching light, colour, or the biology of the eye.' },
  { id: 'refugee-day', month: 6, day: 20, kind: 'fact', summary: '20 June is World Refugee Day, honouring the strength of people forced to flee their homes.', detailBody: 'Access to education is one of the biggest challenges displaced children face worldwide, alongside safety and basic needs.\n\nFor teachers: A sensitive but valuable topic for building empathy and global awareness with older students.' },
  { id: 'yoga-day', month: 6, day: 21, kind: 'fact', summary: '21 June is International Day of Yoga, marking a practice with roots stretching back thousands of years in India.', detailBody: 'The date was chosen because it\'s the summer solstice, the longest day of the year in the Northern Hemisphere, considered significant in Indian tradition.\n\nFor teachers: A good day for a short breathing or stretching break with students, framed around focus rather than religion.' },
  { id: 'comparison-to-self', month: 6, day: 22, kind: 'thought', summary: 'Comparing your current self to your past self is usually more motivating than comparing yourself to someone else.', detailBody: "Progress against your own baseline is something you actually control; comparison to classmates or peers often isn't, and can discourage rather than motivate.\n\nFor teachers: Worth building into feedback — 'compared to your last attempt' rather than 'compared to the top of the class.'" },
  { id: 'olympic-day', month: 6, day: 23, kind: 'fact', summary: '23 June is International Olympic Day, marking the founding of the modern International Olympic Committee in 1894.', detailBody: 'The modern Olympics were revived partly to promote physical education and international friendship through sport, an idea still central to school PE programmes today.\n\nFor teachers: A good day to tie a PE or history lesson to the ancient Greek origins of the Games.' },
  { id: 'amazon-nine-countries', month: 6, day: 24, kind: 'fact', summary: 'The Amazon rainforest spans nine countries, not just Brazil.', detailBody: 'While Brazil holds the largest share, the Amazon also extends into Peru, Colombia, Venezuela, Ecuador, Bolivia, Guyana, Suriname and French Guiana.\n\nFor teachers: A good corrective to the common assumption that the Amazon belongs to one country.' },
  { id: 'reading-choice', month: 6, day: 25, kind: 'thought', summary: 'Letting students choose their own reading material, within reason, builds far more reading motivation than only assigning texts.', detailBody: 'Reluctant readers, in particular, often become willing readers once they\'re allowed to choose a topic or genre that actually interests them.\n\nClassroom idea: Offer two or three text options for the same learning objective when possible.' },
  { id: 'drug-abuse-day', month: 6, day: 26, kind: 'fact', summary: '26 June is the International Day Against Drug Abuse and Illicit Trafficking.', detailBody: "It's a UN awareness day aimed at strengthening action and cooperation to address substance abuse, particularly among young people.\n\nFor teachers: Best addressed briefly and factually, appropriate to the age group, as part of a broader health and wellbeing discussion." },
  { id: 'flamingo-flamboyance', month: 6, day: 27, kind: 'fact', summary: "A group of flamingos is called a 'flamboyance.'", detailBody: 'Flamingos actually get their pink colour from pigments in the algae and shrimp they eat — a flamingo raised on a different diet would stay grey or white.\n\nFor teachers: A fun example of diet directly changing an animal\'s appearance, useful when teaching food chains.' },
  { id: 'exam-anxiety', month: 6, day: 28, kind: 'thought', summary: "A student's fear of failing an exam can itself get in the way of performing well.", detailBody: "This is sometimes called 'test anxiety,' and it can affect capable students disproportionately — a calm, predictable exam routine helps more than last-minute cramming.\n\nFor teachers: Small things — clear instructions, a predictable format — reduce this more than most people expect." },
  { id: 'tropics-day', month: 6, day: 29, kind: 'fact', summary: '29 June is the International Day of the Tropics, recognising the unique opportunities and challenges of tropical regions.', detailBody: "Over 40% of the world's population lives in the tropics, a share expected to keep growing — and most of the world's biodiversity is concentrated there too.\n\nFor teachers: A useful fact for Indian classrooms, given most of India lies within or near the tropics." },
  { id: 'asteroid-day', month: 6, day: 30, kind: 'fact', summary: '30 June is International Asteroid Day, marking the anniversary of the largest asteroid impact in recorded history, the 1908 Tunguska event.', detailBody: 'A relatively small asteroid exploding over Siberia flattened roughly 2,000 square kilometres of forest — a reminder of why scientists track near-Earth objects.\n\nFor teachers: A dramatic real event to use when teaching the solar system\'s smaller, less famous objects.' },
];

const JUL_FACTS: DailyFact[] = [
  { id: 'national-doctors-day', month: 7, day: 1, kind: 'fact', summary: '1 July is National Doctors\' Day in India, honouring the medical profession.', detailBody: 'The date marks the birth and death anniversary of Dr. Bidhan Chandra Roy, physician and former Chief Minister of West Bengal.\n\nFor teachers: A good day to briefly discuss community helpers and professions with younger students.' },
  { id: 'lightning-heat', month: 7, day: 2, kind: 'fact', summary: 'A bolt of lightning is roughly five times hotter than the surface of the Sun.', detailBody: "Lightning can briefly reach around 30,000°C, compared to the Sun's surface temperature of about 5,500°C — the heat just doesn't last long enough to matter the same way.\n\nFor teachers: A dramatic number for a weather or electricity lesson." },
  { id: 'plastic-bag-free-day', month: 7, day: 3, kind: 'fact', summary: '3 July is International Plastic Bag Free Day, raising awareness of plastic pollution.', detailBody: 'A single plastic bag can take hundreds of years to fully break down in the environment, often fragmenting into smaller microplastics long before that.\n\nFor teachers: A good hook for a lesson on waste, recycling, or sustainable alternatives.' },
  { id: 'us-independence', month: 7, day: 4, kind: 'fact', summary: '4 July 1776 marks the date the United States declared independence from Britain.', detailBody: "Comparing it with India's own independence movement — over a century later, against the same colonial power — makes for an interesting compare-and-contrast history lesson.\n\nFor teachers: A neutral, factual comparison point when teaching colonial history more broadly." },
  { id: 'timely-feedback', month: 7, day: 5, kind: 'thought', summary: 'Feedback given close to the moment of the work is more useful than feedback given days later.', detailBody: 'By the time a delayed comment arrives, a student may have already forgotten their exact reasoning — timely feedback, even brief, connects better to the original thinking.\n\nClassroom idea: A quick verbal comment during work time can be more useful than a longer written comment days later.' },
  { id: 'mariana-trench', month: 7, day: 6, kind: 'fact', summary: "The deepest point in Earth's oceans, the Mariana Trench, is deeper than Mount Everest is tall.", detailBody: 'It reaches nearly 11,000 metres down — meaning if Everest were placed at the bottom, its peak would still be underwater by more than 2 km.\n\nFor teachers: A great scale comparison for a lesson on Earth\'s extremes.' },
  { id: 'chocolate-history', month: 7, day: 7, kind: 'fact', summary: '7 July is widely marked as World Chocolate Day.', detailBody: 'Chocolate comes from the cacao bean, first cultivated by Mesoamerican civilisations over 3,000 years ago, originally consumed as a bitter drink, not a sweet.\n\nFor teachers: A fun, light hook for a food-science or history-of-trade lesson.' },
  { id: 'sample-size', month: 7, day: 8, kind: 'thought', summary: "A pattern noticed in just two or three examples isn't yet a reliable rule.", detailBody: 'Small sample sizes can look convincing while actually being coincidence — a habit of asking "how many examples is this based on?" is a simple, useful check.\n\nClassroom idea: When a student generalises from one example, ask for a second and third before accepting the pattern.' },
  { id: 'indian-railways-scale', month: 7, day: 9, kind: 'fact', summary: 'Indian Railways is one of the largest employers in the world, with over a million employees.', detailBody: 'It runs thousands of trains daily, carrying tens of millions of passengers — a genuinely enormous logistical operation.\n\nFor teachers: A good, India-relevant number for a lesson on large-scale systems or transport geography.' },
  { id: 'great-red-spot', month: 7, day: 10, kind: 'fact', summary: "Jupiter's Great Red Spot is a storm larger than Earth that has been raging for at least 150 years.", detailBody: "It's a giant, persistent high-pressure storm system, though observations suggest it has been slowly shrinking in recent decades.\n\nFor teachers: A good example of extreme weather to contrast with Earth's own storms." },
  { id: 'world-population-day', month: 7, day: 11, kind: 'fact', summary: '11 July is World Population Day, marking the year the global population reached 5 billion, in 1987.', detailBody: 'The world\'s population has since grown past 8 billion, with growth rates varying widely between different regions and countries.\n\nFor teachers: A good statistic-rich day for a maths or geography lesson on population data.' },
  { id: 'malala-day', month: 7, day: 12, kind: 'fact', summary: '12 July is recognised by the UN as Malala Day, honouring youth advocacy for girls\' education worldwide.', detailBody: 'It marks the birthday of Malala Yousafzai, who began advocating publicly for girls\' right to education as a teenager and later became the youngest-ever Nobel Peace Prize laureate.\n\nFor teachers: A powerful, age-appropriate example of a young person\'s voice creating real, global change.' },
  { id: 'written-instructions', month: 7, day: 13, kind: 'thought', summary: 'Written instructions get followed more accurately than the same instructions given only verbally.', detailBody: 'Verbal instructions are easy to mishear or forget partway through; having a short written version available (even just on the board) reduces confusion.\n\nClassroom idea: Write the key steps of a multi-step task on the board, not just say them aloud.' },
  { id: 'tallest-tree', month: 7, day: 14, kind: 'fact', summary: 'The tallest known living tree is a coast redwood in California, over 115 metres tall.', detailBody: "That's roughly the height of a 35-storey building, grown from a seed smaller than a grain of rice.\n\nFor teachers: A striking size-comparison fact for a biology or botany lesson." },
  { id: 'specific-goals', month: 7, day: 15, kind: 'thought', summary: "A goal like 'do better in maths' is much less useful than 'show every step for word problems.'", detailBody: "Specific, concrete goals are easier to act on and easier to know when you've achieved them, compared to vague ones.\n\nClassroom idea: Help students rewrite one vague goal into a specific, checkable one this week." },
  { id: 'apollo-11-launch', month: 7, day: 16, kind: 'fact', summary: '16 July 1969 marks the launch of Apollo 11, the mission that first landed humans on the Moon four days later.', detailBody: 'The Moon landing itself happened on 20 July 1969 — the launch and landing are actually two separate historic dates, four days apart.\n\nFor teachers: A good detail to clarify, since many people remember only the landing date.' },
  { id: 'emoji-day', month: 7, day: 17, kind: 'fact', summary: '17 July is informally celebrated as World Emoji Day.', detailBody: 'Emoji originated in Japan in the late 1990s, designed to add emotional tone to short digital messages that plain text often loses.\n\nFor teachers: A light, engaging hook for a lesson on non-verbal communication or the evolution of written language.' },
  { id: 'mandela-day', month: 7, day: 18, kind: 'fact', summary: '18 July is Nelson Mandela International Day, marking his birthday and legacy of reconciliation.', detailBody: "Mandela spent 27 years in prison before becoming South Africa's first democratically elected president, later choosing reconciliation over retribution.\n\nFor teachers: A powerful example for discussing forgiveness, leadership and long-term perseverance." },
  { id: 'multigrade-teaching', month: 7, day: 19, kind: 'thought', summary: 'Teaching several grade levels in one room is a genuine skill, not just a resource limitation to work around.', detailBody: 'Multigrade teaching, common in smaller schools, often benefits from peer-teaching structures where older students help explain concepts to younger ones.\n\nFor teachers: If you teach a mixed-grade or mixed-ability class, structured peer support can lighten the load meaningfully.' },
  { id: 'moon-landing', month: 7, day: 20, kind: 'fact', summary: '20 July 1969 marks the day humans first set foot on the Moon.', detailBody: "Neil Armstrong's words, 'one small step for man, one giant leap for mankind,' were watched live by an estimated 600 million people worldwide.\n\nFor teachers: A good pairing with the 16 July launch-date entry for a short space-race timeline activity." },
  { id: 'antarctica-treaty', month: 7, day: 21, kind: 'fact', summary: 'Antarctica is the only continent with no native human population and no country claiming full sovereignty over it.', detailBody: "It's governed instead by the Antarctic Treaty System, under which multiple countries cooperate for scientific research and agree not to pursue territorial claims.\n\nFor teachers: A good example of international cooperation used as an alternative to competing claims." },
  { id: 'drafts-revision', month: 7, day: 22, kind: 'thought', summary: 'A first draft is meant to be rough — treating it as a final answer is what makes writing feel harder than it needs to be.', detailBody: 'Professional writers routinely produce multiple drafts; the expectation of immediate polish is often what blocks students (and adults) from starting at all.\n\nClassroom idea: Explicitly grade a "first draft" assignment on completion, not polish, to lower the barrier to starting.' },
  { id: 'chandrayaan', month: 7, day: 23, kind: 'fact', summary: 'India\'s Chandrayaan missions have made it one of only a few countries to successfully study the Moon up close.', detailBody: 'Chandrayaan-1 (2008) helped confirm the presence of water molecules on the Moon\'s surface, a significant scientific finding.\n\nFor teachers: A good source of national pride and a strong STEM career example for students interested in space science.' },
  { id: 'hummingbird-heart', month: 7, day: 24, kind: 'fact', summary: "A hummingbird's heart can beat over 1,200 times per minute during flight.", detailBody: 'To sustain that, hummingbirds must eat roughly half their body weight in nectar every day, visiting hundreds of flowers.\n\nFor teachers: A vivid contrast to the earlier "human heart beats 100,000 times a day" fact — a good animal-comparison activity.' },
  { id: 'drowning-prevention-day', month: 7, day: 25, kind: 'fact', summary: '25 July is World Drowning Prevention Day, encouraging basic water-safety awareness.', detailBody: 'Simple measures like supervised swimming and basic water-safety education significantly reduce risk, especially for young children.\n\nFor teachers: Worth a brief, practical safety reminder before school breaks near rivers, ponds or the coast.' },
  { id: 'kargil-vijay-diwas', month: 7, day: 26, kind: 'fact', summary: '26 July is observed in India as Kargil Vijay Diwas, commemorating the 1999 Kargil conflict.', detailBody: 'It is a day of remembrance for the soldiers who served, observed with solemn respect rather than celebration in most schools.\n\nFor teachers: Best handled briefly and respectfully, focused on remembrance rather than the details of conflict.' },
  { id: 'audiobooks-reading', month: 7, day: 27, kind: 'thought', summary: 'Listening to an audiobook engages many of the same comprehension skills as reading print.', detailBody: "While it doesn't build decoding skills the way reading text does, audiobooks build vocabulary, listening comprehension and a love of story just as effectively.\n\nFor teachers: A useful alternative for reluctant readers or long car journeys, not a lesser substitute for 'real' reading." },
  { id: 'nature-conservation-day', month: 7, day: 28, kind: 'fact', summary: '28 July is World Nature Conservation Day, encouraging sustainable use of natural resources.', detailBody: "It's a reminder that conservation isn't only about protecting rare species — it's also about managing everyday resources like soil, water and forests sustainably.\n\nFor teachers: A good day for a simple 'what can our classroom do differently' sustainability discussion." },
  { id: 'tiger-day', month: 7, day: 29, kind: 'fact', summary: '29 July is International Tiger Day, marking global efforts to protect wild tiger populations.', detailBody: 'India is home to more wild tigers than any other country, a result of decades of dedicated conservation work under Project Tiger.\n\nFor teachers: A strong, India-specific conservation success story for an ecosystems or wildlife lesson.' },
  { id: 'friendship-day', month: 7, day: 30, kind: 'fact', summary: '30 July is the International Day of Friendship, recognising the role friendship plays across cultures.', detailBody: 'The UN established the day partly to promote the idea that friendship between people, communities and nations can help build peace.\n\nFor teachers: A nice, simple day for younger students to write a kind note to a classmate.' },
  { id: 'gaps-positive-framing', month: 7, day: 31, kind: 'thought', summary: "A student behind grade level in one skill can still be strong in others — the two facts aren't in conflict.", detailBody: 'Framing a gap as "this specific skill needs more practice" rather than "this student is behind" keeps both the teacher\'s and the student\'s focus on what\'s actionable.\n\nFor teachers: Worth remembering when reporting progress to parents — specific and constructive lands better than a single broad label.' },
];

const AUG_FACTS: DailyFact[] = [
  { id: 'blue-moon', month: 8, day: 1, kind: 'fact', summary: "A 'blue moon' refers to the second full moon in a single calendar month, not a moon that's actually blue.", detailBody: "Because a lunar month is about 29.5 days, most calendar months have only one full moon — a second one is rare enough to have given us the phrase 'once in a blue moon.'\n\nFor teachers: A fun link between an everyday phrase and its actual astronomical origin." },
  { id: 'solar-cell-efficiency', month: 8, day: 2, kind: 'fact', summary: 'The first practical solar cell was built in 1954, converting sunlight to electricity at about 6% efficiency.', detailBody: 'Modern solar panels now regularly exceed 20% efficiency, a steady improvement driven by decades of materials science research.\n\nFor teachers: A good example of incremental technological improvement over a long timescale.' },
  { id: 'explain-back', month: 8, day: 3, kind: 'thought', summary: "A room full of nodding heads doesn't guarantee understanding — it often just means students are being polite.", detailBody: "Asking 'does that make sense?' rarely surfaces confusion; asking a student to explain the idea in their own words usually does.\n\nClassroom idea: Replace 'any questions?' with 'explain this back to me in one sentence.'" },
  { id: 'coffee-trade', month: 8, day: 4, kind: 'fact', summary: "Coffee is one of the world's most-traded agricultural commodities.", detailBody: 'Global coffee cultivation supports the livelihoods of an estimated 25 million farmers, many of them smallholders in tropical regions.\n\nFor teachers: A good economics or geography tie-in on global trade and agriculture.' },
  { id: 'curiosity-rover', month: 8, day: 5, kind: 'fact', summary: "5 August 2012 marks the day NASA's Curiosity rover landed on Mars.", detailBody: 'Its landing sequence, nicknamed "7 minutes of terror," used a rocket-powered sky crane to lower the rover gently onto the Martian surface.\n\nFor teachers: A dramatic real engineering story for a space-exploration lesson.' },
  { id: 'hiroshima-history', month: 8, day: 6, kind: 'fact', summary: '6 August 1945 marks the atomic bombing of Hiroshima, a pivotal and sobering moment in 20th-century history.', detailBody: "It's remembered globally as a turning point that accelerated the end of the Second World War and began the nuclear era.\n\nFor teachers: A sensitive topic best handled factually and respectfully with older students, ideally with careful framing." },
  { id: 'handloom-day', month: 8, day: 7, kind: 'fact', summary: "7 August is National Handloom Day in India, celebrating the country's traditional weaving industry.", detailBody: "India's handloom sector remains one of the largest sources of rural employment after agriculture, producing everything from sarees to home textiles.\n\nFor teachers: A good link to a lesson on traditional crafts, economics, or regional Indian culture." },
  { id: 'memorable-vs-typical', month: 8, day: 8, kind: 'thought', summary: "The most memorable example isn't always the most representative one.", detailBody: 'News and stories tend to highlight the unusual, not the typical — which can quietly distort our sense of how common something actually is.\n\nClassroom idea: When discussing a dramatic news story, ask "is this common, or notable because it\'s rare?"' },
  { id: 'quit-india', month: 8, day: 9, kind: 'fact', summary: "9 August 1942 marks the start of the Quit India Movement, a major push in India's independence struggle.", detailBody: 'Led by Gandhi with the call "Do or Die," it was one of the most widespread mass movements of the independence era.\n\nFor teachers: A good addition to an independence-movement timeline, alongside the Dandi March (12 March).' },
  { id: 'world-lion-day', month: 8, day: 10, kind: 'fact', summary: '10 August is World Lion Day, raising awareness of wild lion conservation.', detailBody: "India is home to the only wild population of Asiatic lions in the world, found in Gujarat's Gir Forest.\n\nFor teachers: A good India-specific example for a conservation or biodiversity lesson." },
  { id: 'delayed-reward', month: 8, day: 11, kind: 'thought', summary: 'Skills that pay off later are harder to stay motivated for than tasks with an immediate reward.', detailBody: 'This is a basic challenge of learning itself — reading fluency, strong maths foundations, and good study habits all pay off later, not immediately.\n\nFor teachers: Small, immediate acknowledgements of progress can bridge the gap while the bigger payoff is still far away.' },
  { id: 'youth-day', month: 8, day: 12, kind: 'fact', summary: '12 August is International Youth Day, recognising the role of young people in society and change.', detailBody: 'It highlights youth voice in areas from education to climate action, treating students as active participants, not just future adults.\n\nFor teachers: A good day to ask students what change they\'d want to see, and really listen to the answer.' },
  { id: 'left-handers-day', month: 8, day: 13, kind: 'fact', summary: '13 August is International Left-Handers Day.', detailBody: 'Left-handed people make up roughly 10% of the population — a minority that historically faced pressure to write with their right hand instead.\n\nFor teachers: A gentle reminder to make sure classroom setups (like scissors and desks) work for left-handed students too.' },
  { id: 'belonging-identity', month: 8, day: 14, kind: 'thought', summary: "Feeling like you belong in a classroom is not a side benefit of learning — it's a condition for it.", detailBody: "Students who don't feel a sense of belonging often disengage academically well before their grades show any sign of a problem.\n\nFor teachers: Small, consistent gestures — a greeting by name, a moment of eye contact — build this more than any single big effort." },
  { id: 'august-etymology', month: 8, day: 15, kind: 'fact', summary: 'August, named after Roman emperor Augustus, is one of two months named after actual people (the other is July, after Julius Caesar).', detailBody: 'Both months were originally shorter under the earlier Roman calendar and were lengthened, partly for political reasons, when they were renamed.\n\nFor teachers: A fun etymology fact for a lesson connecting history and language.' },
  { id: 'largest-employer', month: 8, day: 16, kind: 'fact', summary: "The world's largest employers, by headcount, include national defence forces and a small handful of global retailers.", detailBody: 'Indian Railways (mentioned earlier, 9 July) is typically ranked among the next largest, illustrating just how enormous some single organisations can be.\n\nFor teachers: A good comparative-scale fact for a lesson on large organisations or economics.' },
  { id: 'full-circle-rainbow', month: 8, day: 17, kind: 'fact', summary: 'A rainbow can theoretically be a full circle, not just an arc — we just don\'t usually get to see the bottom half.', detailBody: 'From an aeroplane, or from a high enough vantage point, a full circular rainbow is sometimes visible, since the ground normally blocks the lower half.\n\nFor teachers: A nice follow-up to the earlier rainbow-physics fact (1 March).' },
  { id: 'telegraph-speed', month: 8, day: 18, kind: 'fact', summary: 'The first transatlantic telegraph cable (1858) could send only about two words per minute.', detailBody: 'Compare that to modern undersea fibre-optic cables, which can carry terabits of data per second — a staggering jump in just over 150 years.\n\nFor teachers: A good number-based way to show how dramatically communication speed has changed.' },
  { id: 'photography-day', month: 8, day: 19, kind: 'fact', summary: '19 August is World Photography Day, marking the announcement of the daguerreotype photographic process in 1839.', detailBody: 'Early photographs required several minutes of stillness to capture a single image — a far cry from a modern phone\'s instant photo.\n\nFor teachers: A good link to a lesson on how technology can dramatically compress the time a task takes.' },
  { id: 'sadbhavana-diwas', month: 8, day: 20, kind: 'fact', summary: '20 August is observed in India as Sadbhavana Diwas, promoting communal harmony and national integration.', detailBody: "It marks the birth anniversary of former Prime Minister Rajiv Gandhi and encourages a pledge to uphold peace and unity across communities.\n\nFor teachers: A good, neutral day for a short class discussion on respecting differences within a community." },
  { id: 'reading-fluency-comprehension', month: 8, day: 21, kind: 'thought', summary: "Reading quickly isn't the same as reading well — comprehension, not just speed, is the real goal.", detailBody: 'Pushing for faster reading without checking comprehension can actually train students to skim rather than understand.\n\nFor teachers: When assessing reading, check understanding alongside speed, not instead of it.' },
  { id: 'other-planet-rings', month: 8, day: 22, kind: 'fact', summary: 'Saturn is not the only planet with rings — Jupiter, Uranus and Neptune all have them too, just much fainter.', detailBody: "Saturn's rings are unusually bright and wide, which is why they're the ones most people picture, but ring systems are actually common among gas giants.\n\nFor teachers: A good correction to the assumption that ring systems are unique to Saturn." },
  { id: 'slave-trade-remembrance', month: 8, day: 23, kind: 'fact', summary: '23 August is the International Day for Remembrance of the Slave Trade and its Abolition.', detailBody: 'It commemorates the 1791 uprising in Saint-Domingue (Haiti) that became a major turning point toward the trade\'s eventual abolition.\n\nFor teachers: Best introduced briefly and factually with older students as part of world history.' },
  { id: 'assessment-beyond-exams', month: 8, day: 24, kind: 'thought', summary: "A single exam score is a snapshot, not a full picture of a student's understanding.", detailBody: 'Projects, class participation, and short regular checks together paint a more complete and fairer picture than one high-stakes test alone.\n\nFor teachers: Worth keeping in mind when a generally strong student has one uncharacteristically poor test day.' },
  { id: 'voyager-neptune', month: 8, day: 25, kind: 'fact', summary: "25 August 1989 marks Voyager 2's flyby of Neptune, our only close-up look at the planet to date.", detailBody: 'Launched in 1977, Voyager 2 remains the only spacecraft to have visited all four of the solar system\'s giant planets.\n\nFor teachers: A great example of a single long-running mission delivering discoveries across more than a decade.' },
  { id: 'womens-equality-day', month: 8, day: 26, kind: 'fact', summary: "26 August is Women's Equality Day, marking the certification of the 19th Amendment granting American women the right to vote in 1920.", detailBody: 'It\'s often used more broadly to mark progress toward gender equality worldwide, alongside days like International Women\'s Day (8 March).\n\nFor teachers: A useful pairing with the 8 March entry when building a broader lesson on the history of equal rights.' },
  { id: 'soil-microorganisms', month: 8, day: 27, kind: 'fact', summary: 'A single teaspoon of soil can contain more microorganisms than there are people on Earth.', detailBody: 'Healthy soil is teeming with bacteria, fungi and other microbes that break down organic matter and recycle nutrients for plants.\n\nFor teachers: A good way to make "soil" feel like a living system, not just dirt, in an ecosystems lesson.' },
  { id: 'imitation-originality', month: 8, day: 28, kind: 'thought', summary: 'Learning to imitate a style closely often comes before, not instead of, developing an original one.', detailBody: 'Many artists, writers and musicians deliberately study and copy existing work early on — imitation is often a stepping stone to originality, not its opposite.\n\nFor teachers: Worth remembering before discouraging a student\'s early work for being "too similar" to something else.' },
  { id: 'national-sports-day', month: 8, day: 29, kind: 'fact', summary: '29 August is National Sports Day in India, marking the birthday of hockey legend Major Dhyan Chand.', detailBody: 'Dhyan Chand helped India win three consecutive Olympic gold medals in hockey (1928, 1932, 1936) and is still widely regarded as one of the greatest players the sport has seen.\n\nFor teachers: A good day for a PE-focused activity or a short talk on sportsmanship.' },
  { id: 'great-indian-bustard', month: 8, day: 30, kind: 'fact', summary: "One of the heaviest flying birds in the world, the Great Indian Bustard, is now critically endangered, with only a few hundred left in the wild.", detailBody: "Conservation efforts are focused mainly in Rajasthan, the bird's last major stronghold in India.\n\nFor teachers: A good, India-specific conservation case study, more immediate than a distant example." },
  { id: 'month-end-reflection-aug', month: 8, day: 31, kind: 'thought', summary: "Looking back at a month's small wins is a habit worth building, not just an end-of-year exercise.", detailBody: 'Regular, short reflection — even a single sentence — helps both students and teachers notice progress that would otherwise go unnoticed.\n\nAs August ends: one sentence on what went well this month is worth writing down, even briefly.' },
];

const SEP_FACTS: DailyFact[] = [
  { id: 'email-spam-history', month: 9, day: 1, kind: 'fact', summary: 'The first practical email spam message was sent in 1978, decades before spam became a household annoyance.', detailBody: 'It was sent to several hundred ARPANET users advertising a product — an unwanted preview of a problem that would grow enormously with the internet\'s scale.\n\nFor teachers: A good example of how a small early problem can grow dramatically alongside a technology\'s adoption.' },
  { id: 'coconut-day', month: 9, day: 2, kind: 'fact', summary: "2 September is World Coconut Day, recognising the coconut's importance across tropical economies, including India's.", detailBody: 'Nearly every part of the coconut palm is used — for food, oil, rope (coir), and building material — earning it the nickname "tree of life" in many coastal regions.\n\nFor teachers: A good, India-relevant example of a plant used for far more than just its most obvious product.' },
  { id: 'error-analysis', month: 9, day: 3, kind: 'thought', summary: 'A wrong answer, examined closely, often teaches more than simply marking it incorrect and moving on.', detailBody: 'The specific type of mistake — a sign error, a misread instruction, a misunderstood concept — points to exactly what needs attention next.\n\nClassroom idea: Occasionally ask students to explain why a wrong answer seemed right to them at the time.' },
  { id: 'big-bang-expansion', month: 9, day: 4, kind: 'fact', summary: "The 'Big Bang' wasn't an explosion in space — it was the rapid expansion of space itself.", detailBody: "There was no 'centre' the universe expanded outward from in the way an explosion has a centre; space itself has been stretching in every direction ever since.\n\nFor teachers: A common misconception worth correcting directly when introducing the origin of the universe." },
  { id: 'pythagoras-india', month: 9, day: 5, kind: 'fact', summary: "The 'Pythagorean theorem' was known and used by several ancient civilisations, including in India and Babylon, before Pythagoras.", detailBody: 'Evidence from the Baudhayana Sulba Sutra, an ancient Indian mathematical text, shows the same relationship being used centuries before it was attributed to the Greek mathematician.\n\nFor teachers: A good reminder that mathematical discovery is rarely the work of just one person or one culture.' },
  { id: 'silk-thread-length', month: 9, day: 6, kind: 'fact', summary: 'A single silkworm cocoon can unravel into a thread stretching over 900 metres unbroken.', detailBody: 'It takes several thousand cocoons to produce just one kilogram of raw silk — a labour-intensive process behind a fabric most people rarely think twice about.\n\nFor teachers: A good link to India\'s traditional silk-weaving regions, like those celebrated on National Handloom Day (7 August).' },
  { id: 'clean-air-day', month: 9, day: 7, kind: 'fact', summary: '7 September is the International Day of Clean Air for Blue Skies.', detailBody: "Air pollution affects both outdoor and indoor air, and disproportionately harms children, whose lungs are still developing.\n\nFor teachers: A good tie-in with an environmental science or public-health lesson." },
  { id: 'literacy-day', month: 9, day: 8, kind: 'fact', summary: "8 September is International Literacy Day, marking UNESCO's global push toward universal literacy.", detailBody: 'Literacy is now recognised as a foundation not just for further education, but for health, employment and civic participation.\n\nFor teachers: A fitting day to celebrate reading progress with your own class, however small.' },
  { id: 'asking-for-help', month: 9, day: 9, kind: 'thought', summary: 'Teaching students how to ask for help clearly is itself a skill worth teaching, not something assumed they already have.', detailBody: '"I don\'t get it" gives a teacher little to work with; "I understood step one but got stuck at step two" gives them somewhere to start.\n\nClassroom idea: Model the difference between a vague and a specific help request explicitly.' },
  { id: 'amazon-river-volume', month: 9, day: 10, kind: 'fact', summary: 'The Amazon river system carries more water than the next seven largest rivers in the world combined.', detailBody: 'Its enormous volume comes from draining a rainforest basin that receives extraordinarily heavy annual rainfall.\n\nFor teachers: A good scale fact to pair with earlier Amazon-related entries (24 June) on the rainforest itself.' },
  { id: 'robot-etymology', month: 9, day: 11, kind: 'fact', summary: "The word 'robot' comes from a 1920s Czech play, from a word meaning 'forced labour.'", detailBody: 'Playwright Karel Čapek\'s "R.U.R." introduced the term to describe artificial workers, decades before real robots existed.\n\nFor teachers: A fun etymology fact for a lesson connecting language, literature and technology.' },
  { id: 'carbon-structures', month: 9, day: 12, kind: 'fact', summary: 'Diamonds and pencil lead (graphite) are both made of pure carbon, arranged differently.', detailBody: 'The difference in how the carbon atoms are bonded and arranged is the sole reason one is the hardest natural material and the other is soft enough to write with.\n\nFor teachers: A great, simple example of how structure — not just material — determines properties.' },
  { id: 'headline-vs-story', month: 9, day: 13, kind: 'thought', summary: 'A headline is written to grab attention, not to summarise fairly — reading past it matters.', detailBody: "Even accurate headlines are often written to be as dramatic as the facts allow, which can shift a reader's first impression before they've read a single detail.\n\nClassroom idea: Compare how two different headlines describe the exact same event." },
  { id: 'hindi-diwas', month: 9, day: 14, kind: 'fact', summary: '14 September is Hindi Diwas in India, marking the day Hindi was adopted as an official language of the Union in 1949.', detailBody: 'India recognises 22 scheduled languages in its Constitution, alongside hundreds of other languages and dialects spoken across the country.\n\nFor teachers: A good day to celebrate the specific language(s) spoken at home by students in a multilingual classroom.' },
  { id: 'engineers-day', month: 9, day: 15, kind: 'fact', summary: "15 September is Engineer's Day in India, marking the birth anniversary of engineer and statesman M. Visvesvaraya.", detailBody: 'Visvesvaraya designed flood-protection and irrigation systems still valued for their engineering long after his time, and later served as Diwan of Mysore.\n\nFor teachers: A strong Indian STEM role model for students interested in engineering.' },
  { id: 'ozone-layer-day', month: 9, day: 16, kind: 'fact', summary: '16 September marks the International Day for the Preservation of the Ozone Layer.', detailBody: "It celebrates the 1987 Montreal Protocol, widely considered one of the most successful international environmental agreements — the ozone layer is now slowly recovering.\n\nFor teachers: A rare, genuinely hopeful example for an environmental science lesson — global cooperation actually fixing a problem." },
  { id: 'peer-teaching', month: 9, day: 17, kind: 'thought', summary: 'Students explaining a concept to classmates often reinforces it for the explainer as much as the listener.', detailBody: 'This connects to the earlier "protégé effect" (8 February) — structured peer teaching benefits both the stronger and the developing student, differently but genuinely.\n\nFor teachers: Worth trying deliberately, rather than only as an informal "ask your neighbour" moment.' },
  { id: 'la-paz-altitude', month: 9, day: 18, kind: 'fact', summary: "La Paz, Bolivia, is the world's highest capital city, sitting at an altitude of over 3,600 metres.", detailBody: 'At that height, the air contains noticeably less oxygen, which is one reason many endurance athletes train at high altitude.\n\nFor teachers: A good example connecting geography directly to human biology.' },
  { id: 'bamboo-growth', month: 9, day: 19, kind: 'fact', summary: "Bamboo is technically a grass, not a tree, and it's one of the fastest-growing plants on Earth.", detailBody: 'Some species can grow nearly a metre in a single day under ideal conditions — far faster than any woody tree.\n\nFor teachers: A fun botany fact that challenges the assumption that all tall plants are trees.' },
  { id: 'collective-nouns', month: 9, day: 20, kind: 'fact', summary: "A group of owls is called a 'parliament.'", detailBody: '"Group names for animals (a murder of crows, a parliament of owls) mostly come from old English hunting and folklore traditions, not scientific classification.\n\nFor teachers: A fun link to the earlier crow fact (14 May) — collective nouns as a light language activity.' },
  { id: 'peace-day', month: 9, day: 21, kind: 'fact', summary: '21 September is the International Day of Peace, established by the United Nations.', detailBody: "It's marked worldwide with a global ceasefire appeal and a minute of silence at UN Headquarters.\n\nFor teachers: A fitting day for a short classroom discussion on resolving conflict peacefully, scaled to any age group." },
  { id: 'autumn-equinox', month: 9, day: 22, kind: 'fact', summary: 'Around 22 September, day and night are roughly equal length again, marking the autumn equinox in the Northern Hemisphere.', detailBody: 'It\'s the seasonal counterpart to the March equinox, and marks the Sun crossing back over the equator on its apparent path south.\n\nFor teachers: A good half-year check-in with the earlier equinox entry (20 March).' },
  { id: 'sign-languages-day', month: 9, day: 23, kind: 'fact', summary: '23 September is the International Day of Sign Languages.', detailBody: "Sign languages are full, complex languages with their own grammar — not simply a gestural version of spoken language.\n\nFor teachers: A good opportunity to teach a handful of basic signs as a fun, inclusive classroom activity." },
  { id: 'consistent-habits', month: 9, day: 24, kind: 'thought', summary: 'Small, consistent habits usually beat occasional bursts of intense effort over time.', detailBody: 'Ten minutes of practice most days adds up to more than an occasional two-hour session, partly because consistency also builds retention between sessions.\n\nFor teachers: Worth explaining directly to students who cram — the total hours matter less than how they\'re spread out.' },
  { id: 'thar-desert-population', month: 9, day: 25, kind: 'fact', summary: 'The Thar Desert is one of the most densely populated deserts in the world.', detailBody: 'Unlike many deserts, the Thar supports a substantial population through adapted farming, livestock herding and, increasingly, wind and solar energy projects.\n\nFor teachers: A good corrective to the assumption that deserts are always empty of people.' },
  { id: 'fiction-empathy', month: 9, day: 26, kind: 'thought', summary: 'Reading fiction, not just informational text, measurably builds empathy and perspective-taking.', detailBody: 'Following a character\'s inner thoughts and motivations gives practice imagining other people\'s perspectives — a skill that transfers well beyond the story itself.\n\nFor teachers: Worth remembering when fiction gets deprioritised in favour of "more useful" non-fiction reading.' },
  { id: 'tourism-day', month: 9, day: 27, kind: 'fact', summary: '27 September is World Tourism Day, marking the social, cultural and economic value of travel.', detailBody: 'Tourism is one of the largest employers globally and a major source of income for many regions rich in natural or historical sites, including much of India.\n\nFor teachers: A good geography tie-in — ask students to "plan a trip" to a place they\'re studying.' },
  { id: 'rabies-day', month: 9, day: 28, kind: 'fact', summary: '28 September is World Rabies Day, raising awareness of a preventable disease through responsible pet care and vaccination.', detailBody: 'Simple measures like vaccinating pets have made rabies extremely rare in many countries, though it remains a risk in some regions.\n\nFor teachers: Best kept brief and factual — a good link to a lesson on vaccines and disease prevention generally.' },
  { id: 'heart-day', month: 9, day: 29, kind: 'fact', summary: '29 September is World Heart Day, promoting awareness of heart health.', detailBody: 'Simple habits like regular movement, discussed even briefly with students, help build lifelong health awareness early.\n\nFor teachers: A good excuse for a short active break or a PE-focused activity.' },
  { id: 'translation-day', month: 9, day: 30, kind: 'fact', summary: '30 September is International Translation Day, recognising the work of translators and interpreters worldwide.', detailBody: "Translation isn't just word-for-word substitution — a good translator carries meaning, tone and cultural context across languages, which is much harder than it sounds.\n\nFor teachers: A good day to discuss India's own everyday translation — many students already move fluidly between two or three languages without thinking of it as 'translating.'" },
];

const OCT_FACTS: DailyFact[] = [
  { id: 'older-persons-day', month: 10, day: 1, kind: 'fact', summary: '1 October is the International Day of Older Persons.', detailBody: "It's a reminder that older generations often carry knowledge and oral history that isn't written down anywhere else.\n\nFor teachers: A nice prompt for students to interview a grandparent or elder about how school was different in their time." },
  { id: 'shastri-birthday', month: 10, day: 2, kind: 'fact', summary: "India's second Prime Minister, Lal Bahadur Shastri, shares his birthday with Mahatma Gandhi, on 2 October.", detailBody: 'Shastri is remembered for the slogan "Jai Jawan Jai Kisan" ("Hail the Soldier, Hail the Farmer"), highlighting both the military and farmers during a difficult period for India.\n\nFor teachers: A good reminder that this date honours two significant figures in Indian history, not just one.' },
  { id: 'termite-mounds', month: 10, day: 3, kind: 'fact', summary: 'Termite mounds can include built-in ventilation systems that keep the internal temperature remarkably stable.', detailBody: 'Some termite species build mounds with internal chimneys and tunnels that passively regulate airflow — architects have studied these designs for natural cooling ideas.\n\nFor teachers: A great example of nature "inventing" engineering solutions long before humans did.' },
  { id: 'animal-day', month: 10, day: 4, kind: 'fact', summary: '4 October is World Animal Day, promoting animal welfare across the world.', detailBody: 'The date was originally chosen to align with the feast day of St. Francis of Assisi, known for his connection to animals.\n\nFor teachers: A nice day for younger students to talk about caring for a pet or local animals responsibly.' },
  { id: 'world-teachers-day', month: 10, day: 5, kind: 'fact', summary: "5 October is World Teachers' Day, UNESCO's global recognition of the teaching profession.", detailBody: "It exists alongside India's own Teachers' Day (5 September) — different dates, same underlying purpose: recognising the work teachers do worldwide.\n\nFor teachers: A second well-earned nod to the profession, a month after India's own." },
  { id: 'optional-extra-practice', month: 10, day: 6, kind: 'thought', summary: 'Not every student needs the same amount of practice to reach the same level of confidence.', detailBody: 'Offering optional extra practice for those who want it, without making it feel remedial, respects that pace genuinely varies without slowing the whole class down.\n\nClassroom idea: Keep a small set of "extra practice if you want it" problems available, framed as optional, not required.' },
  { id: 'cotton-day', month: 10, day: 7, kind: 'fact', summary: '7 October is World Cotton Day. India is one of the largest producers of cotton in the world.', detailBody: 'Cotton has been cultivated on the Indian subcontinent for thousands of years, with archaeological evidence of cotton textiles dating back over 5,000 years.\n\nFor teachers: A good link to both agriculture and the history of textiles and trade.' },
  { id: 'air-force-day', month: 10, day: 8, kind: 'fact', summary: '8 October is Indian Air Force Day, marking the founding of the Indian Air Force in 1932.', detailBody: "It's one of the largest air forces in the world today, and the day is usually marked with flying displays.\n\nFor teachers: A good hook for a lesson on flight, aerodynamics, or Indian defence history, age-appropriately." },
  { id: 'world-post-day', month: 10, day: 9, kind: 'fact', summary: '9 October is World Post Day, marking the founding of the Universal Postal Union in 1874.', detailBody: 'Before email, the postal service was the primary way messages crossed long distances — the UPU still coordinates mail delivery between almost every country on Earth.\n\nFor teachers: A good, tangible way to introduce how global cooperation enables something as ordinary as sending a letter.' },
  { id: 'mental-health-day', month: 10, day: 10, kind: 'fact', summary: '10 October is World Mental Health Day, encouraging open, supportive conversations about mental wellbeing.', detailBody: 'A calm, consistent classroom environment, and simply noticing when a student seems off, can make a meaningful difference alongside professional support when needed.\n\nFor teachers: Best framed around everyday supportive habits, not diagnosis — refer concerns to appropriate school support systems.' },
  { id: 'girl-child-day', month: 10, day: 11, kind: 'fact', summary: "11 October is the International Day of the Girl Child, focused on girls' rights and opportunities, especially education.", detailBody: 'Globally, girls still face greater barriers to completing school than boys in many regions, though the gap has narrowed significantly in recent decades.\n\nFor teachers: A good day to highlight girls\' achievements in your own classroom or school.' },
  { id: 'columbus-1492', month: 10, day: 12, kind: 'fact', summary: "12 October 1492 marks the date Christopher Columbus's expedition reached the Americas.", detailBody: 'It is remembered very differently by different groups — as a historic voyage by some, and as the start of colonisation and hardship for indigenous peoples by others.\n\nFor teachers: A good example of how the same historical event can be taught from more than one perspective.' },
  { id: 'draft-two-normal', month: 10, day: 13, kind: 'thought', summary: 'The best version of an idea is rarely the first one — but it\'s always the one you have to write down to get there.', detailBody: "Revision isn't a sign the first attempt failed; it's simply the next expected step in getting anywhere good.\n\nFor teachers: Framing 'draft two' as normal progress, not correction, changes how students feel about revising their own work." },
  { id: 'world-standards-day', month: 10, day: 14, kind: 'fact', summary: '14 October is World Standards Day, marking the importance of shared technical standards worldwide.', detailBody: 'Standards are why a charger made in one country works with a device made in another, or why screw sizes match across manufacturers — invisible agreements that make modern life work.\n\nFor teachers: A good, concrete example of cooperation you can point to in almost any object in the room.' },
  { id: 'apj-kalam', month: 10, day: 15, kind: 'fact', summary: '15 October marks the birthday of Dr. A.P.J. Abdul Kalam, aerospace scientist and former President of India.', detailBody: 'Known as the "Missile Man of India" for his work on India\'s space and defence programmes, Kalam was also a passionate advocate for science education among young people.\n\nFor teachers: A strong Indian STEM role model, especially fitting for a science or careers-focused lesson.' },
  { id: 'world-food-day', month: 10, day: 16, kind: 'fact', summary: '16 October is World Food Day, marking the founding of the UN Food and Agriculture Organization.', detailBody: 'It raises awareness of both food security challenges and the importance of sustainable agriculture worldwide.\n\nFor teachers: A good tie-in with a nutrition, agriculture, or "where does our food come from" lesson.' },
  { id: 'poverty-eradication-day', month: 10, day: 17, kind: 'fact', summary: '17 October is the International Day for the Eradication of Poverty.', detailBody: 'Access to quality education is widely recognised as one of the strongest long-term tools for breaking cycles of poverty across generations.\n\nFor teachers: A meaningful reminder of the broader stakes behind the everyday work of teaching.' },
  { id: 'decibel-scale', month: 10, day: 18, kind: 'fact', summary: "A 'decibel' scale for measuring sound is logarithmic, not linear — a 10-decibel increase means the sound is 10 times more intense.", detailBody: "This is why a rock concert (about 110 dB) isn't just 'a bit louder' than a normal conversation (about 60 dB) — it's roughly 100,000 times more intense.\n\nFor teachers: A good, slightly surprising number for a lesson on sound and logarithmic scales." },
  { id: 'language-of-instruction', month: 10, day: 19, kind: 'thought', summary: 'Learning a new subject and learning in a new language at the same time is a genuinely harder task than doing either alone.', detailBody: "For students learning in a language that isn't their first, extra time and scaffolding for the language itself — not just the subject content — makes a real difference.\n\nFor teachers: Worth separating 'doesn't understand the concept' from 'doesn't yet have the vocabulary for it' before assuming a knowledge gap." },
  { id: 'richter-scale', month: 10, day: 20, kind: 'fact', summary: "The 'Richter scale' for earthquakes is also logarithmic — a magnitude 6 quake releases about 32 times more energy than a magnitude 5.", detailBody: "This is why moving from a 'moderate' to a 'major' earthquake on the scale represents an enormous jump in destructive energy, not a small one.\n\nFor teachers: A good pairing with the decibel-scale fact (18 October) when teaching logarithmic scales." },
  { id: 'chess-india-origin', month: 10, day: 21, kind: 'fact', summary: 'Chess originated in India around the 6th century, under the name chaturanga, before spreading to Persia and eventually Europe.', detailBody: "The game's pieces evolved along the way — the modern 'bishop,' for instance, was originally an elephant in the Indian version.\n\nFor teachers: A good India-origin story for a lesson on how games and ideas spread and change across cultures." },
  { id: 'antarctica-ice-water', month: 10, day: 22, kind: 'fact', summary: "Antarctica holds about 70% of the world's fresh water, locked up as ice.", detailBody: "If all of Antarctica's ice sheet melted, global sea levels would rise by an estimated 60 metres — though this would take an extraordinarily long time under current conditions.\n\nFor teachers: A good, striking number for a climate or geography lesson, without needing to speculate about timelines." },
  { id: 'mole-day', month: 10, day: 23, kind: 'fact', summary: "Mole Day, informally observed by chemistry teachers on 23 October (10/23), celebrates Avogadro's number.", detailBody: "Avogadro's number (about 6.022 × 10²³) is the basis of the 'mole,' a unit chemists use to count enormous quantities of atoms or molecules.\n\nFor teachers: A fun, chemistry-specific day if you teach or touch on the subject." },
  { id: 'united-nations-day', month: 10, day: 24, kind: 'fact', summary: '24 October is United Nations Day, marking the founding of the UN in 1945.', detailBody: 'The UN was created after the Second World War specifically to help prevent future large-scale conflicts through international cooperation.\n\nFor teachers: A good anchor date for a lesson on international organisations and diplomacy.' },
  { id: 'identity-based-habits', month: 10, day: 25, kind: 'thought', summary: "Framing a habit as 'I am someone who reads' tends to stick better than 'I should read more.'", detailBody: 'Identity-based framing connects a habit to who a person sees themselves as, which tends to be more durable than framing built only around outcomes or willpower.\n\nFor teachers: Worth trying with students — "you\'re becoming a strong writer" lands differently than "you need to write more."' },
  { id: 'india-borders', month: 10, day: 26, kind: 'fact', summary: 'India shares land borders with six countries, and a maritime border with several more.', detailBody: 'Its neighbours by land are Pakistan, China, Nepal, Bhutan, Bangladesh and Myanmar — a good one for students to be able to name confidently.\n\nFor teachers: A solid, testable geography fact worth revisiting with a map.' },
  { id: 'sputnik-1', month: 10, day: 27, kind: 'fact', summary: 'The first artificial satellite, Sputnik 1, was about the size of a beach ball, yet it kicked off the entire space race.', detailBody: 'Launched by the Soviet Union in 1957, it orbited Earth for about three months, transmitting a simple radio beep that could be picked up by amateur radio operators worldwide.\n\nFor teachers: A good example of how a technically simple device can have an outsized historical impact.' },
  { id: 'angel-falls', month: 10, day: 28, kind: 'fact', summary: 'The tallest waterfall in the world, Angel Falls in Venezuela, drops for nearly a full kilometre.', detailBody: "It's so tall that much of the water evaporates or is blown away as mist before it even reaches the bottom.\n\nFor teachers: A dramatic 'tallest of its kind' fact for a geography lesson on landforms." },
  { id: 'arpanet-first-message', month: 10, day: 29, kind: 'fact', summary: '29 October 1969 marks the first message ever sent over ARPANET, the precursor to today\'s internet.', detailBody: 'The message was meant to be the word "LOGIN" — but the system crashed after just the first two letters, "LO," making that the actual first message sent.\n\nFor teachers: A fun, humanising detail — even history-making technology has an awkward first attempt.' },
  { id: 'confidence-accuracy', month: 10, day: 30, kind: 'thought', summary: "Being very confident about something doesn't make it more likely to be true.", detailBody: 'Confidence and accuracy are only loosely related — people (including experts) are often just as confident when wrong as when right.\n\nClassroom idea: Occasionally ask students to rate their own confidence alongside their answer, then compare the two over time.' },
  { id: 'national-unity-day', month: 10, day: 31, kind: 'fact', summary: '31 October is National Unity Day in India, marking the birth anniversary of Sardar Vallabhbhai Patel.', detailBody: 'Patel is remembered for peacefully integrating over 500 princely states into the newly independent Indian union, a task of enormous scale and diplomacy.\n\nFor teachers: A good moment to discuss unity and cooperation as active, ongoing work, not just a slogan.' },
];

const NOV_FACTS: DailyFact[] = [
  { id: 'state-formation-day', month: 11, day: 1, kind: 'fact', summary: '1 November marks the formation day of several Indian states, including Karnataka, Kerala and Andhra Pradesh, following the linguistic reorganisation of states in 1956.', detailBody: "India's states were substantially redrawn along linguistic lines in 1956, which is why so many state 'formation days' fall on the same date.\n\nFor teachers: A good day to ask students about their own state's formation, language and history." },
  { id: 'brief-review-habit', month: 11, day: 2, kind: 'thought', summary: "A quick review of last month's topic keeps it from fading, even a short one.", detailBody: 'Without occasional review, previously learned material tends to fade well before an exam — a few minutes of spaced review protects against this more efficiently than a long re-teach later.\n\nClassroom idea: Open one lesson a week with a two-minute recall of something from a few weeks back.' },
  { id: 'ocean-tides', month: 11, day: 3, kind: 'fact', summary: "Ocean tides are caused mainly by the Moon's gravity pulling on Earth's water.", detailBody: "The Sun also contributes to tides, but because it's so much farther away, its pull is weaker than the Moon's despite the Sun's far greater mass.\n\nFor teachers: A good example of how distance can matter more than size in gravitational effects." },
  { id: 'bristlecone-pine', month: 11, day: 4, kind: 'fact', summary: 'One bristlecone pine tree in California is estimated to be over 4,800 years old — older than the Great Pyramid of Giza.', detailBody: 'Trees like this survive so long partly by growing extremely slowly in harsh, high-altitude conditions that few other organisms can tolerate.\n\nFor teachers: A striking way to make deep historical time feel more tangible, using something still alive today.' },
  { id: 'infinity-symbol', month: 11, day: 5, kind: 'fact', summary: 'The mathematical symbol for infinity (∞) was introduced by English mathematician John Wallis in 1655.', detailBody: "Its shape was likely inspired by an already-existing symbol used in Roman numerals for 1,000 — reused because it visually suggested something endless.\n\nFor teachers: A fun, lesser-known bit of maths notation history." },
  { id: 'starling-murmuration', month: 11, day: 6, kind: 'fact', summary: "A 'murmuration' is the term for the swirling, coordinated flight pattern large flocks of starlings perform.", detailBody: "No single bird leads the group — each bird simply reacts to the movement of its nearest neighbours, and the complex pattern emerges from those simple, local rules.\n\nFor teachers: A great real-world example of complex behaviour emerging from simple rules, useful even outside biology." },
  { id: 'marie-curie-birthday', month: 11, day: 7, kind: 'fact', summary: '7 November marks the birthday of Marie Curie, born in 1867.', detailBody: "Curie's research on radioactivity was so pioneering that some of her original notebooks are still radioactive today, over a century later, and are kept in lead-lined boxes.\n\nFor teachers: A striking, slightly eerie detail that makes the reality of radioactivity concrete for students." },
  { id: 'specific-positive-note', month: 11, day: 8, kind: 'thought', summary: 'A short note about something specific a student did well often matters more to a family than a general progress report.', detailBody: 'Specific, positive communication home builds trust that makes harder conversations (when they\'re needed) land better later.\n\nFor teachers: Worth trying — one specific positive note home this month, unprompted by any problem.' },
  { id: 'antikythera-mechanism', month: 11, day: 9, kind: 'fact', summary: 'The Antikythera mechanism, found in a shipwreck near Greece, is a roughly 2,000-year-old mechanical device that could predict astronomical positions.', detailBody: "It's often called the world's first known analogue computer, and its true complexity wasn't fully understood until X-ray imaging techniques were applied to it in the 2000s.\n\nFor teachers: A great example that impressive engineering isn't only a modern achievement." },
  { id: 'doppler-effect', month: 11, day: 10, kind: 'fact', summary: "The 'Doppler effect' is why a passing ambulance siren sounds higher-pitched as it approaches and lower as it moves away.", detailBody: 'The same effect, applied to light instead of sound, is how astronomers determine whether distant stars and galaxies are moving toward or away from us.\n\nFor teachers: A good everyday example (traffic, sirens) before extending the idea to something as abstract as an expanding universe.' },
  { id: 'national-education-day', month: 11, day: 11, kind: 'fact', summary: "11 November is National Education Day in India, marking the birth anniversary of Maulana Abul Kalam Azad, India's first Education Minister.", detailBody: "Azad played a key role in establishing several of India's premier educational institutions in the years after independence.\n\nFor teachers: A fitting day to reflect on how far access to education in India has come — and how far it still has to go." },
  { id: 'fibonacci-nickname', month: 11, day: 12, kind: 'fact', summary: "The mathematician 'Fibonacci' actually called himself Leonardo of Pisa — 'Fibonacci' was a nickname given centuries later.", detailBody: 'His 1202 book, "Liber Abaci," also helped introduce the Hindu-Arabic numeral system (the 0-9 digits we still use) to Europe.\n\nFor teachers: A good companion to the earlier zero/India maths-history entry (2 January).' },
  { id: 'world-kindness-day', month: 11, day: 13, kind: 'fact', summary: '13 November is World Kindness Day.', detailBody: "Research on 'prosocial behaviour' consistently finds that small acts of kindness measurably improve the mood of both the giver and the receiver.\n\nFor teachers: A nice, low-effort day for a class kindness challenge — even something as small as one specific compliment each." },
  { id: 'play-as-cognitive-work', month: 11, day: 14, kind: 'thought', summary: 'Play is now recognised by child-development researchers as genuine cognitive work, not simply a break from learning.', detailBody: "Through unstructured play, children practise negotiation, planning and problem-solving in ways structured lessons often can't replicate.\n\nFor teachers: A fitting thought to pair with Children's Day itself." },
  { id: 'termite-classification', month: 11, day: 15, kind: 'fact', summary: 'Termites are actually more closely related to cockroaches than to most other insects commonly grouped with them.', detailBody: 'Despite their ant-like colony behaviour, genetic studies place termites within the cockroach order — a good example of appearance not always matching biological classification.\n\nFor teachers: A good link when teaching that classification is based on shared ancestry, not just similar behaviour.' },
  { id: 'tolerance-day', month: 11, day: 16, kind: 'fact', summary: '16 November is the International Day for Tolerance.', detailBody: 'It was established partly in response to rising intolerance and discrimination worldwide, encouraging respect for differences in belief, culture and background.\n\nFor teachers: A good day for a classroom discussion on respecting different viewpoints, scaled appropriately to age.' },
  { id: 'palindrome-numbers', month: 11, day: 17, kind: 'fact', summary: "A 'palindrome' number reads the same forwards and backwards, like 121 or 3,443.", detailBody: 'Palindromes appear in language too ("level," "madam") and are a fun, simple way to explore symmetry in both maths and words.\n\nFor teachers: A quick, engaging warm-up activity for either a maths or language lesson.' },
  { id: 'wright-brothers-first-flight', month: 11, day: 18, kind: 'fact', summary: "The Wright brothers' first powered flight in 1903 lasted just 12 seconds and covered about 37 metres.", detailBody: "That's shorter than the wingspan of some modern passenger aircraft — a reminder of how far aviation technology has come in just over a century.\n\nFor teachers: A good 'small beginnings, huge consequences' example for a history-of-technology lesson." },
  { id: 'international-mens-day', month: 11, day: 19, kind: 'fact', summary: "19 November is International Men's Day, recognising positive models of masculinity and men's health and wellbeing.", detailBody: "It's observed alongside International Women's Day (8 March) as part of a broader focus on gender issues affecting everyone.\n\nFor teachers: Best framed around role models and healthy relationships, in an age-appropriate way." },
  { id: 'universal-childrens-day', month: 11, day: 20, kind: 'fact', summary: "20 November is Universal Children's Day, marking the UN's adoption of the Convention on the Rights of the Child in 1989.", detailBody: "The Convention sets out children's rights to education, health, protection and participation — the most widely ratified human rights treaty in history.\n\nFor teachers: A good companion date to India's own Children's Day, a week earlier." },
  { id: 'world-television-day', month: 11, day: 21, kind: 'fact', summary: "21 November is World Television Day, recognising television's role in shaping public opinion and sharing information.", detailBody: 'Even in a world of streaming and social media, television remains one of the most widely accessible mass media in many parts of the world.\n\nFor teachers: A good hook for a media-literacy discussion on how any screen, old or new, shapes what we think we know.' },
  { id: 'protected-reading-time', month: 11, day: 22, kind: 'thought', summary: 'Regular, protected independent reading time, even just 10-15 minutes, compounds significantly over a school year.', detailBody: "It's one of the simplest interventions with consistently good evidence behind it — the challenge is usually protecting the time, not proving the value.\n\nFor teachers: Worth defending as non-negotiable time, even when the schedule feels tight." },
  { id: 'rosetta-stone', month: 11, day: 23, kind: 'fact', summary: "The 'Rosetta Stone' allowed scholars to finally decode ancient Egyptian hieroglyphs, because it repeated the same text in three scripts.", detailBody: 'One of those scripts, Ancient Greek, was already understood — giving scholars a way to work backward and crack the hieroglyphic writing system.\n\nFor teachers: A great example of how comparing a known and unknown side by side can unlock understanding.' },
  { id: 'origin-of-species-published', month: 11, day: 24, kind: 'fact', summary: "Charles Darwin published 'On the Origin of Species' on 24 November 1859.", detailBody: 'The first print run of 1,250 copies sold out on its very first day, a strong public reaction to what was, at the time, a genuinely radical idea.\n\nFor teachers: Pairs with the earlier Darwin birthday entry (12 February) for a two-part evolution mini-unit.' },
  { id: 'violence-against-women-day', month: 11, day: 25, kind: 'fact', summary: '25 November is the International Day for the Elimination of Violence against Women.', detailBody: 'It marks the start of a UN 16-day campaign of activism on the issue, running through to Human Rights Day (10 December).\n\nFor teachers: Best handled with older students, framed around respect and safety in relationships generally.' },
  { id: 'constitution-day', month: 11, day: 26, kind: 'fact', summary: '26 November is Constitution Day in India, marking the day the Constituent Assembly formally adopted the Constitution in 1949.', detailBody: 'It came into effect a little over a month later, on 26 January 1950 — the date now celebrated as Republic Day.\n\nFor teachers: A good pairing with the Republic Day entry (26 January) to explain the difference between "adopted" and "came into effect."' },
  { id: 'motivation-dip-normal', month: 11, day: 27, kind: 'thought', summary: "Motivation naturally dips partway through a long school term — that's normal, not a sign something is wrong.", detailBody: "Breaking a long stretch into smaller visible milestones helps sustain effort better than relying on willpower alone across months.\n\nFor teachers: A short, visible 'we're halfway there' marker can genuinely help during a long term." },
  { id: 'black-hole-misnomer', month: 11, day: 28, kind: 'fact', summary: "A black hole isn't literally a hole — it's an extremely dense concentration of matter with gravity so strong that not even light can escape it.", detailBody: "The 'hole' in the name is misleading; a more accurate description would be an extremely compact, extremely massive object.\n\nFor teachers: Worth clarifying directly, since the name itself creates a common misconception." },
  { id: 'first-public-aquarium', month: 11, day: 29, kind: 'fact', summary: "The world's first public aquarium opened in London in 1853, popularising the very word 'aquarium.'", detailBody: 'Before that, keeping and displaying live sea creatures for public viewing was extremely rare, since maintaining stable water conditions was a genuine technical challenge.\n\nFor teachers: A fun link to a lesson on ecosystems or the history of museums (18 May).' },
  { id: 'nepal-flag-shape', month: 11, day: 30, kind: 'fact', summary: "Nepal is the only country in the world with a national flag that isn't rectangular.", detailBody: 'Its flag is made of two stacked triangular pennants, each carrying its own symbolic meaning tied to the Himalayan mountains and Nepali royal history.\n\nFor teachers: A fun geography fact — a good one to pair with a "flags of the world" activity.' },
];

const DEC_FACTS: DailyFact[] = [
  { id: 'world-aids-day', month: 12, day: 1, kind: 'fact', summary: '1 December is World AIDS Day, promoting awareness and support for people affected by HIV/AIDS worldwide.', detailBody: 'Global awareness and access to treatment have improved dramatically since the day was first observed in 1988.\n\nFor teachers: Best kept brief and factual, focused on awareness and compassion rather than detailed medical content, appropriate to age group.' },
  { id: 'pollution-control-day', month: 12, day: 2, kind: 'fact', summary: '2 December is observed in India as National Pollution Control Day, marking industrial safety and environmental protection.', detailBody: 'It commemorates the importance of strict safety standards in industry, established in the aftermath of one of the most serious industrial accidents in history.\n\nFor teachers: Best handled briefly, focused on the importance of safety regulation rather than the event\'s details.' },
  { id: 'disabilities-day', month: 12, day: 3, kind: 'fact', summary: '3 December is the International Day of Persons with Disabilities.', detailBody: 'It promotes the rights and wellbeing of people with disabilities and encourages more inclusive, accessible classrooms and communities.\n\nFor teachers: A good pairing with the earlier Louis Braille entry (4 January) for a lesson on accessible design.' },
  { id: 'navy-day', month: 12, day: 4, kind: 'fact', summary: '4 December is Indian Navy Day, marking a key naval operation during the 1971 India-Pakistan war.', detailBody: "It's now marked mainly as a tribute to the Indian Navy's role in national defence, observed with naval displays in coastal cities.\n\nFor teachers: A good, brief entry point for discussing India's coastline and maritime geography." },
  { id: 'world-soil-day', month: 12, day: 5, kind: 'fact', summary: '5 December is World Soil Day, highlighting the importance of healthy soil for food production.', detailBody: 'It can take hundreds of years for nature to form just a few centimetres of fertile topsoil, which is why soil erosion is treated as a serious long-term concern.\n\nFor teachers: A good pairing with the earlier "soil is alive" fact (27 August).' },
  { id: 'mahaparinirvan-din', month: 12, day: 6, kind: 'fact', summary: '6 December is observed in India as Mahaparinirvan Din, the death anniversary of Dr. B.R. Ambedkar.', detailBody: 'It is marked respectfully across the country, particularly at his memorial in Mumbai, honouring his lifelong work for social justice and equality.\n\nFor teachers: A quiet, reflective day, well paired with the earlier Ambedkar Jayanti entry (14 April).' },
  { id: 'civil-aviation-day', month: 12, day: 7, kind: 'fact', summary: '7 December is International Civil Aviation Day, marking the 1944 Chicago Convention that established global rules for air travel.', detailBody: "That agreement is why an aircraft can safely and predictably fly between countries with completely different languages, laws and air-traffic systems.\n\nFor teachers: A good, concrete example of how shared rules make complex global systems work smoothly." },
  { id: 'term-review-pacing', month: 12, day: 8, kind: 'thought', summary: "Reviewing across the whole term's material in small regular doses beats one long review session right before an exam.", detailBody: 'This again reflects the spacing effect (5 April) — a little review each day in the final weeks tends to outperform a single marathon revision session.\n\nFor teachers: Worth planning explicitly into the final weeks of a term, not left to happen informally.' },
  { id: 'anti-corruption-day', month: 12, day: 9, kind: 'fact', summary: '9 December is International Anti-Corruption Day.', detailBody: 'It marks the anniversary of the UN Convention against Corruption, encouraging transparency and accountability in public life.\n\nFor teachers: A good, age-appropriate entry point into a discussion on honesty and fairness in shared systems, like classroom rules themselves.' },
  { id: 'human-rights-day', month: 12, day: 10, kind: 'fact', summary: '10 December is Human Rights Day, marking the adoption of the Universal Declaration of Human Rights in 1948.', detailBody: 'The Declaration set out, for the first time, a shared global statement of rights every person is considered entitled to, regardless of country.\n\nFor teachers: A good pairing with Constitution Day (26 November) when discussing rights, both national and international.' },
  { id: 'mountain-day', month: 12, day: 11, kind: 'fact', summary: '11 December is International Mountain Day.', detailBody: "Mountains cover about a quarter of the world's land surface and are the water source for roughly half the world's population, via the rivers that begin there.\n\nFor teachers: A good link between geography (mountains) and the earlier water-cycle content (22 March)." },
  { id: 'mantis-shrimp-punch', month: 12, day: 12, kind: 'fact', summary: 'The mantis shrimp can strike with a punch fast enough to briefly boil the water around it.', detailBody: 'Its claw accelerates so quickly that it creates a cavitation bubble that collapses with a flash of light and heat, entirely underwater.\n\nFor teachers: A dramatic, safely factual animal-adaptation example that reliably grabs students\' attention.' },
  { id: 'senet-board-game', month: 12, day: 13, kind: 'fact', summary: 'The oldest known board game, Senet, was played in ancient Egypt over 5,000 years ago.', detailBody: 'Archaeologists still debate the exact rules, since no complete rulebook from the time has survived — only the boards and pieces themselves.\n\nFor teachers: A fun example of how much can be inferred, and how much remains genuinely unknown, from archaeological evidence alone.' },
  { id: 'energy-conservation-day', month: 12, day: 14, kind: 'fact', summary: '14 December is National Energy Conservation Day in India.', detailBody: 'Simple habits — switching off unused lights and fans, using natural light where possible — add up meaningfully across an entire school over a year.\n\nFor teachers: A good day for a practical, hands-on "energy audit" activity around the classroom or school.' },
  { id: 'feedback-culture', month: 12, day: 15, kind: 'thought', summary: 'A classroom where mistakes are treated as normal information, not embarrassment, produces students who take more academic risks.', detailBody: "How a teacher responds to the first wrong answer of the day often sets the tone for whether other students are willing to attempt one too.\n\nFor teachers: Worth noticing your own instinctive reaction to a wrong answer — it's more visible to students than it might feel." },
  { id: 'vijay-diwas', month: 12, day: 16, kind: 'fact', summary: '16 December is observed in India as Vijay Diwas, marking the end of the 1971 India-Pakistan war.', detailBody: 'It is a day of remembrance for those who served, observed with solemn respect in most schools.\n\nFor teachers: Best kept brief and respectful, similar in tone to Kargil Vijay Diwas (26 July).' },
  { id: 'lightning-energy-unusable', month: 12, day: 17, kind: 'fact', summary: 'A single lightning strike carries enough energy to toast roughly 100,000 slices of bread — though harnessing it directly has never proven practical.', detailBody: "Lightning's energy is real but arrives in far too short and unpredictable a burst to usefully capture with current technology.\n\nFor teachers: A fun follow-up to the earlier 'lightning is hotter than the Sun' fact (2 July) — impressive power, but not a usable energy source (yet)." },
  { id: 'migrants-day', month: 12, day: 18, kind: 'fact', summary: '18 December is International Migrants Day.', detailBody: 'It recognises the contributions migrants make to the communities and countries they move to, and the challenges many face along the way.\n\nFor teachers: A good, sensitive entry point for discussing migration within India\'s own history, from Partition-era movement to present-day internal migration.' },
  { id: 'goa-liberation-day', month: 12, day: 19, kind: 'fact', summary: '19 December is Goa Liberation Day, marking the end of Portuguese colonial rule in Goa in 1961.', detailBody: 'Goa remained under Portuguese control for over a decade after most of India gained independence in 1947, a detail often left out of the simplified "India became independent in 1947" story.\n\nFor teachers: A good, specific example of how independence happened at different times in different parts of the country.' },
  { id: 'human-solidarity-day', month: 12, day: 20, kind: 'fact', summary: '20 December is International Human Solidarity Day, encouraging global cooperation to address shared challenges.', detailBody: "It's a reminder that problems like climate change, disease and poverty rarely respect national borders, which is part of why international cooperation matters.\n\nFor teachers: A good, broad framing day for a discussion of any global-scale challenge students are curious about." },
  { id: 'winter-solstice', month: 12, day: 21, kind: 'fact', summary: 'Around 21 December, the Northern Hemisphere experiences its shortest day and longest night of the year — the winter solstice.', detailBody: "It's the seasonal counterpart to the June solstice, and the point at which the Sun's apparent path is furthest south of the equator.\n\nFor teachers: A good three-way pairing with both equinox entries (20 March, 22 September) to complete a full seasons unit." },
  { id: 'national-mathematics-day', month: 12, day: 22, kind: 'fact', summary: '22 December is National Mathematics Day in India, marking the birth anniversary of Srinivasa Ramanujan.', detailBody: 'Ramanujan made extraordinary contributions to number theory and mathematical analysis, much of it developed independently before he ever reached Cambridge.\n\nFor teachers: A good pairing with the earlier Ramanujan entry (24 March) for a short profile of his life and work.' },
  { id: 'farmers-day', month: 12, day: 23, kind: 'fact', summary: '23 December is National Farmers\' Day in India, honouring the country\'s farmers and their role in food security.', detailBody: 'Agriculture remains one of the largest sources of employment in India, even as the sector modernises with new tools and techniques.\n\nFor teachers: A good link to a lesson on where food actually comes from, especially for urban students.' },
  { id: 'rest-is-progress', month: 12, day: 24, kind: 'thought', summary: "Rest is not the opposite of progress — for both students and teachers, it's part of how the brain consolidates what's been learned.", detailBody: 'Continuous effort without any breaks tends to reduce both performance and retention over time, not just comfort.\n\nAs the year winds down: a genuine break, without guilt, is a reasonable and useful thing to take.' },
  { id: 'newton-birthday-calendar', month: 12, day: 25, kind: 'fact', summary: 'Isaac Newton was born on 25 December 1642, according to the calendar in use in England at the time.', detailBody: 'Under the calendar used in most of Europe at the time, the date would actually correspond to early January — a good example of how calendar systems themselves can complicate "simple" historical dates.\n\nFor teachers: A fun, slightly tricky fact-checking exercise: what does "born on 25 December" actually mean across different calendars?' },
  { id: 'boxing-day', month: 12, day: 26, kind: 'fact', summary: '26 December is observed as Boxing Day in several countries, traditionally a day for giving to those in need.', detailBody: 'Its exact origins are debated, but one common explanation ties it to alms boxes traditionally opened and distributed the day after Christmas.\n\nFor teachers: A light, optional mention rather than a major classroom topic, useful mainly for general-knowledge trivia.' },
  { id: 'comet-tail-direction', month: 12, day: 27, kind: 'fact', summary: "A comet's tail always points away from the Sun, regardless of which direction the comet itself is travelling.", detailBody: 'This is because the tail is formed by solar wind and radiation pressure pushing gas and dust away from the comet, not by its motion through space.\n\nFor teachers: A good corrective to the intuitive (but wrong) assumption that a tail simply trails behind an object\'s direction of travel.' },
  { id: 'indian-national-congress', month: 12, day: 28, kind: 'fact', summary: '28 December 1885 marks the founding of the Indian National Congress, which later became central to India\'s independence movement.', detailBody: 'It began as a moderate platform for political dialogue with the British colonial government, and only gradually became the movement associated with full independence.\n\nFor teachers: A good reminder that historical movements often start with more modest goals than where they eventually end up.' },
  { id: 'year-in-review', month: 12, day: 29, kind: 'thought', summary: 'A full year offers more useful lessons in review than in the moment it\'s lived.', detailBody: 'Patterns — what worked, what consistently didn\'t — are usually easier to see looking back over months than they were day to day.\n\nFor teachers: A single sentence on "what I\'d do differently next year" is worth more than it takes to write.' },
  { id: 'kipling-birthday', month: 12, day: 30, kind: 'fact', summary: 'Author Rudyard Kipling, born 30 December 1865 in Bombay (now Mumbai), set much of his most famous writing, including "The Jungle Book," in India.', detailBody: 'Kipling remains a complicated figure historically, but his stories are still widely read as classics of children\'s literature.\n\nFor teachers: A good literature tie-in, with room for an honest, age-appropriate conversation about historical context if relevant to the class.' },
  { id: 'year-end-fresh-start', month: 12, day: 31, kind: 'thought', summary: 'The end of one year and the start of the next is really just one ordinary night in between — the meaning we give the date is what makes it useful.', detailBody: "That's not a reason to skip new-year reflection — it's a reason to use any natural marker, not just this one, whenever a fresh start would actually help.\n\nAs the year ends: whatever this year's classroom taught you, it's worth carrying one specific lesson into the next." },
];

export const DAILY_FACTS: DailyFact[] = [
  ...JAN_FACTS, ...FEB_FACTS, ...MAR_FACTS, ...APR_FACTS, ...MAY_FACTS, ...JUN_FACTS,
  ...JUL_FACTS, ...AUG_FACTS, ...SEP_FACTS, ...OCT_FACTS, ...NOV_FACTS, ...DEC_FACTS,
];

function pad2(n: number): string {
  return n < 10 ? `0${n}` : `${n}`;
}

function dateKey(month: number, day: number): string {
  return `${pad2(month)}-${pad2(day)}`;
}

// Built once at module load for O(1) lookup — see getDailyFact. Keying by
// 'MM-DD' (not a dayOfYear index) is what makes leap years a non-issue: 1
// March always maps to the same entry whether or not 29 February existed
// that year, since nothing here is an offset from the start of the year.
const DAILY_FACTS_BY_DATE: Map<string, DailyFact> = new Map(
  DAILY_FACTS.map((f) => [dateKey(f.month, f.day), f])
);

// Deliberately no dayOfYear-modulo fallback here: every calendar date
// (365, plus 29 February for leap years) has an authored entry — see
// dailyContent.test.ts's "full calendar coverage" check — so a miss here
// would mean a genuine data bug, not an expected gap. Falling back to the
// first entry keeps the app from crashing (and stays deterministic for the
// missing date) without masking the bug by silently improvising content.
export function getDailyFact(date: Date = new Date()): DailyFact {
  const key = dateKey(date.getMonth() + 1, date.getDate());
  return DAILY_FACTS_BY_DATE.get(key) ?? DAILY_FACTS[0];
}
